INSERT INTO questions (id, subject, subject_name, track, difficulty, topic, question, options_json, correct_answer, explanation, trap, shortcut_trick, tags_json) VALUES ('m_012', 'math', 'คณิตศาสตร์', 'Gifted', 3, 'เลขหลักหน่วยของเลขยกกำลัง (รูปแบบที่ 12)', 'เลขหลักหน่วยของผลลัพธ์ \( 7^{2032} \) มีค่าเท่ากับข้อใด', '["1","3","5","7"]', 0, '1) หาคาบวัฏจักรหลักหน่วยของ 7^n: [7, 9, 3, 1] (ซ้ำทุก 4 ตัว)
