INSERT INTO questions (id, subject, subject_name, track, difficulty, topic, question, options_json, correct_answer, explanation, trap, shortcut_trick, tags_json) VALUES ('m_021', 'math', 'คณิตศาสตร์', 'Regular', 2, 'สมการขาสัตว์และหัวสัตว์ (รูปแบบที่ 21)', 'ในฟาร์มแห่งหนึ่งมีไก่และกระต่ายรวมกัน 62 ตัว เมื่อนับขารวมกันได้ 178 ขา อยากทราบว่าในฟาร์มนี้มีกระต่ายทั้งหมดกี่ตัว', '["27 ตัว","35 ตัว","29 ตัว","25 ตัว"]', 0, '1) สมมติให้เป็นไก่ทั้งหมด (ตัวละ 2 ขา): มีขา = 62 × 2 = 124 ขา
