INSERT INTO questions (id, subject, subject_name, track, difficulty, topic, question, options_json, correct_answer, explanation, trap, shortcut_trick, tags_json) VALUES ('m_041', 'math', 'คณิตศาสตร์', 'Regular', 2, 'สมการขาสัตว์และหัวสัตว์ (รูปแบบที่ 41)', 'ในฟาร์มแห่งหนึ่งมีไก่และกระต่ายรวมกัน 102 ตัว เมื่อนับขารวมกันได้ 298 ขา อยากทราบว่าในฟาร์มนี้มีกระต่ายทั้งหมดกี่ตัว', '["47 ตัว","55 ตัว","49 ตัว","45 ตัว"]', 0, '1) สมมติให้เป็นไก่ทั้งหมด (ตัวละ 2 ขา): มีขา = 102 × 2 = 204 ขา
INSERT INTO questions (id, subject, subject_name, track, difficulty, topic, question, options_json, correct_answer, explanation, trap, shortcut_trick, tags_json) VALUES ('m_042', 'math', 'คณิตศาสตร์', 'Gifted', 3, 'เลขหลักหน่วยของเลขยกกำลัง (รูปแบบที่ 42)', 'เลขหลักหน่วยของผลลัพธ์ \( 7^{2062} \) มีค่าเท่ากับข้อใด', '["9","1","3","5"]', 0, '1) หาคาบวัฏจักรหลักหน่วยของ 7^n: [7, 9, 3, 1] (ซ้ำทุก 4 ตัว)
INSERT INTO questions (id, subject, subject_name, track, difficulty, topic, question, options_json, correct_answer, explanation, trap, shortcut_trick, tags_json) VALUES ('m_043', 'math', 'คณิตศาสตร์', 'Gifted', 3, 'มุมระหว่างเข็มนาฬิกา (รูปแบบที่ 43)', 'เมื่อเวลา 11:55 น. มุมแหลม/มุมป้านขนาดเล็กระหว่างเข็มสั้นและเข็มยาวมีขนาดกี่องศา', '["27.5 องศา","42.5 องศา","7.5 องศา","57.5 องศา"]', 0, 'ใช้สูตรมุมระหว่างเข็มนาฬิกา: \( |30H - 5.5M| = |30(11) - 5.5(55)| = 27.5^\circ \)', 'เข็มสั้นขยับตามเข็มยาวเสมอ (0.5 องศาต่อนาที)', 'สูตรลัด: |30 × ชั่วโมง - 5.5 × นาที|', '["มุมระหว่างเข็มนาฬิกา (รูปแบบที่ 43)","Gifted"]');
INSERT INTO questions (id, subject, subject_name, track, difficulty, topic, question, options_json, correct_answer, explanation, trap, shortcut_trick, tags_json) VALUES ('m_044', 'math', 'คณิตศาสตร์', 'Gifted', 2, 'โจทย์อัตราการทำงานและท่อน้ำ (รูปแบบที่ 44)', 'ท่อ A เปิดน้ำเข้าถังเต็มใน 6 ชั่วโมง ส่วนท่อ B เปิดเต็มใน 6 ชั่วโมง ถ้าเปิดท่อ A และ B พร้อมกัน น้ำจะเต็มถังในเวลากี่ชั่วโมง', '["\\( \\displaystyle \\frac{36}{12} \\) ชั่วโมง","\\( \\displaystyle \\frac{12}{2} \\) ชั่วโมง","\\( \\displaystyle \\frac{38}{12} \\) ชั่วโมง","12 ชั่วโมง"]', 0, '1) ใน 1 ชั่วโมง ท่อ A ทำได้ \( \frac{1}{6} \), ท่อ B ทำได้ \( \frac{1}{6} \)
INSERT INTO questions (id, subject, subject_name, track, difficulty, topic, question, options_json, correct_answer, explanation, trap, shortcut_trick, tags_json) VALUES ('m_045', 'math', 'คณิตศาสตร์', 'Gifted', 3, 'อัตราเร็วเรือพายทวนน้ำ-ตามน้ำ (รูปแบบที่ 45)', 'เรือยนต์แล่นตามน้ำด้วยความเร็ว 69 กม./ชม. และแล่นทวนน้ำด้วยความเร็ว 61 กม./ชม. จงหาความเร็วของกระแสน้ำ', '["4 กิโลเมตรต่อชั่วโมง","65 กิโลเมตรต่อชั่วโมง","6 กิโลเมตรต่อชั่วโมง","8 กิโลเมตรต่อชั่วโมง"]', 0, '1) ความเร็วตามน้ำ = v_เรือ + v_น้ำ = 69
INSERT INTO questions (id, subject, subject_name, track, difficulty, topic, question, options_json, correct_answer, explanation, trap, shortcut_trick, tags_json) VALUES ('m_046', 'math', 'คณิตศาสตร์', 'Gifted', 3, 'เศษส่วนซ้อนหลายชั้น (รูปแบบที่ 46)', 'ถ้า \( \displaystyle x = 2 + \cfrac{1}{4 + \cfrac{1}{4}} \) จงหาค่าของ \( x \) ในรูปเศษส่วนอย่างต่ำ', '["\\( \\displaystyle \\frac{38}{17} \\)","\\( \\displaystyle \\frac{37}{17} \\)","\\( \\displaystyle \\frac{40}{17} \\)","\\( \\displaystyle \\frac{38}{18} \\)"]', 0, '1) ชั้นล่างสุด: \( 4 + \frac{1}{4} = \frac{17}{4} \)
INSERT INTO questions (id, subject, subject_name, track, difficulty, topic, question, options_json, correct_answer, explanation, trap, shortcut_trick, tags_json) VALUES ('m_047', 'math', 'คณิตศาสตร์', 'Gifted', 3, 'เรขาคณิตและพื้นที่แรเงารูปใบไม้ (รูปแบบที่ 47)', 'รูปสี่เหลี่ยมจัตุรัสยาวด้านละ 28 เซนติเมตร มีพื้นที่แรเงารูปใบไม้ตรงกลาง จงหาพื้นที่แรเงา (กำหนด \( \pi = \frac{22}{7} \))', '["448 ตารางเซนติเมตร","462 ตารางเซนติเมตร","434 ตารางเซนติเมตร","392 ตารางเซนติเมตร"]', 0, 'สูตรพื้นที่แรเงารูปใบไม้ในสี่เหลี่ยมจัตุรัส: \( \text{พื้นที่} = \frac{4}{7} \times r^2 = \frac{4}{7} \times 28^2 = 448 \text{ ตร.ซม.} \)', 'รูปใบไม้เกิดจากเซกเตอร์ 2 รูปซ้อนทับกัน', 'สูตรลัดพื้นที่ใบไม้ = (4/7) × ด้าน²', '["เรขาคณิตและพื้นที่แรเงารูปใบไม้ (รูปแบบที่ 47)","Gifted"]');
INSERT INTO questions (id, subject, subject_name, track, difficulty, topic, question, options_json, correct_answer, explanation, trap, shortcut_trick, tags_json) VALUES ('m_048', 'math', 'คณิตศาสตร์', 'Regular', 2, 'การนับและการจับมือแข่งขัน (รูปแบบที่ 48)', 'ในงานเลี้ยงมีคนมาร่วมงาน 54 คน ถ้าทุกคนจับมือทักทายกันครบทุกคน จะเกิดการจับมือทั้งหมดกี่ครั้ง', '["1431 ครั้ง","2862 ครั้ง","1485 ครั้ง","1428 ครั้ง"]', 0, 'ใช้สูตรจับมือ: \( \frac{n(n - 1)}{2} = \frac{54 \times 53}{2} = 1431 \text{ ครั้ง} \)', 'อย่าลืมหาร 2 เพราะจับคู่กัน 1 ครั้งได้ 2 คน', 'สูตรลัดจับมือ: [n × (n - 1)] ÷ 2', '["การนับและการจับมือแข่งขัน (รูปแบบที่ 48)","Regular"]');
INSERT INTO questions (id, subject, subject_name, track, difficulty, topic, question, options_json, correct_answer, explanation, trap, shortcut_trick, tags_json) VALUES ('m_049', 'math', 'คณิตศาสตร์', 'Regular', 2, 'แผนภาพเวนน์-ออยเลอร์และเซต (รูปแบบที่ 49)', 'นักเรียน 138 คน ชอบเรียนคณิตศาสตร์ 69 คน ชอบวิทยาศาสตร์ 67 คน และชอบทั้งสองวิชา 59 คน มีนักเรียนที่ไม่ชอบทั้งสองวิชานี้กี่คน', '["61 คน","65 คน","59 คน","59 คน"]', 0, '1) จำนวนคนที่ชอบอย่างน้อย 1 วิชา = 69 + 67 - 59 = 77 คน
INSERT INTO questions (id, subject, subject_name, track, difficulty, topic, question, options_json, correct_answer, explanation, trap, shortcut_trick, tags_json) VALUES ('m_050', 'math', 'คณิตศาสตร์', 'Gifted', 3, 'อนุกรมเศษส่วนเทเลสโคปิก (รูปแบบที่ 50)', 'จงหาค่าของผลบวก \( \displaystyle \frac{1}{1 \times 2} + \frac{1}{2 \times 3} + \frac{1}{3 \times 4} + ... + \frac{1}{60 \times 61} \)', '["\\( \\displaystyle \\frac{60}{61} \\)","\\( \\displaystyle \\frac{59}{61} \\)","\\( \\displaystyle \\frac{61}{62} \\)","1"]', 0, 'แยกเศษส่วนย่อยตัดกัน: \( (1 - \frac{1}{2}) + (\frac{1}{2} - \frac{1}{3}) + ... + (\frac{1}{60} - \frac{1}{61}) = 1 - \frac{1}{61} = \frac{60}{61} \)', 'พจน์ตรงกลางจะตัดกันหมด เหลือพจน์แรกและพจน์สุดท้าย', 'สูตรลัดเทเลสโคปิก: 1 - 1/(ตัวสุดท้าย)', '["อนุกรมเศษส่วนเทเลสโคปิก (รูปแบบที่ 50)","Gifted"]');
