INSERT INTO questions (id, subject, subject_name, track, difficulty, topic, question, options_json, correct_answer, explanation, trap, shortcut_trick, tags_json) VALUES ('m_061', 'math', 'คณิตศาสตร์', 'Regular', 2, 'สมการขาสัตว์และหัวสัตว์ (รูปแบบที่ 61)', 'ในฟาร์มแห่งหนึ่งมีไก่และกระต่ายรวมกัน 142 ตัว เมื่อนับขารวมกันได้ 418 ขา อยากทราบว่าในฟาร์มนี้มีกระต่ายทั้งหมดกี่ตัว', '["67 ตัว","75 ตัว","69 ตัว","65 ตัว"]', 0, '1) สมมติให้เป็นไก่ทั้งหมด (ตัวละ 2 ขา): มีขา = 142 × 2 = 284 ขา
INSERT INTO questions (id, subject, subject_name, track, difficulty, topic, question, options_json, correct_answer, explanation, trap, shortcut_trick, tags_json) VALUES ('m_062', 'math', 'คณิตศาสตร์', 'Gifted', 3, 'เลขหลักหน่วยของเลขยกกำลัง (รูปแบบที่ 62)', 'เลขหลักหน่วยของผลลัพธ์ \( 2^{2082} \) มีค่าเท่ากับข้อใด', '["4","6","8","0"]', 0, '1) หาคาบวัฏจักรหลักหน่วยของ 2^n: [2, 4, 8, 6] (ซ้ำทุก 4 ตัว)
INSERT INTO questions (id, subject, subject_name, track, difficulty, topic, question, options_json, correct_answer, explanation, trap, shortcut_trick, tags_json) VALUES ('m_063', 'math', 'คณิตศาสตร์', 'Gifted', 3, 'มุมระหว่างเข็มนาฬิกา (รูปแบบที่ 63)', 'เมื่อเวลา 09:45 น. มุมแหลม/มุมป้านขนาดเล็กระหว่างเข็มสั้นและเข็มยาวมีขนาดกี่องศา', '["22.5 องศา","37.5 องศา","2.5 องศา","52.5 องศา"]', 0, 'ใช้สูตรมุมระหว่างเข็มนาฬิกา: \( |30H - 5.5M| = |30(9) - 5.5(45)| = 22.5^\circ \)', 'เข็มสั้นขยับตามเข็มยาวเสมอ (0.5 องศาต่อนาที)', 'สูตรลัด: |30 × ชั่วโมง - 5.5 × นาที|', '["มุมระหว่างเข็มนาฬิกา (รูปแบบที่ 63)","Gifted"]');
INSERT INTO questions (id, subject, subject_name, track, difficulty, topic, question, options_json, correct_answer, explanation, trap, shortcut_trick, tags_json) VALUES ('m_064', 'math', 'คณิตศาสตร์', 'Gifted', 2, 'โจทย์อัตราการทำงานและท่อน้ำ (รูปแบบที่ 64)', 'ท่อ A เปิดน้ำเข้าถังเต็มใน 6 ชั่วโมง ส่วนท่อ B เปิดเต็มใน 8 ชั่วโมง ถ้าเปิดท่อ A และ B พร้อมกัน น้ำจะเต็มถังในเวลากี่ชั่วโมง', '["\\( \\displaystyle \\frac{48}{14} \\) ชั่วโมง","\\( \\displaystyle \\frac{14}{2} \\) ชั่วโมง","\\( \\displaystyle \\frac{50}{14} \\) ชั่วโมง","14 ชั่วโมง"]', 0, '1) ใน 1 ชั่วโมง ท่อ A ทำได้ \( \frac{1}{6} \), ท่อ B ทำได้ \( \frac{1}{8} \)
INSERT INTO questions (id, subject, subject_name, track, difficulty, topic, question, options_json, correct_answer, explanation, trap, shortcut_trick, tags_json) VALUES ('m_065', 'math', 'คณิตศาสตร์', 'Gifted', 3, 'อัตราเร็วเรือพายทวนน้ำ-ตามน้ำ (รูปแบบที่ 65)', 'เรือยนต์แล่นตามน้ำด้วยความเร็ว 91 กม./ชม. และแล่นทวนน้ำด้วยความเร็ว 79 กม./ชม. จงหาความเร็วของกระแสน้ำ', '["6 กิโลเมตรต่อชั่วโมง","85 กิโลเมตรต่อชั่วโมง","8 กิโลเมตรต่อชั่วโมง","10 กิโลเมตรต่อชั่วโมง"]', 0, '1) ความเร็วตามน้ำ = v_เรือ + v_น้ำ = 91
INSERT INTO questions (id, subject, subject_name, track, difficulty, topic, question, options_json, correct_answer, explanation, trap, shortcut_trick, tags_json) VALUES ('m_066', 'math', 'คณิตศาสตร์', 'Gifted', 3, 'เศษส่วนซ้อนหลายชั้น (รูปแบบที่ 66)', 'ถ้า \( \displaystyle x = 1 + \cfrac{1}{4 + \cfrac{1}{4}} \) จงหาค่าของ \( x \) ในรูปเศษส่วนอย่างต่ำ', '["\\( \\displaystyle \\frac{21}{17} \\)","\\( \\displaystyle \\frac{20}{17} \\)","\\( \\displaystyle \\frac{23}{17} \\)","\\( \\displaystyle \\frac{21}{18} \\)"]', 0, '1) ชั้นล่างสุด: \( 4 + \frac{1}{4} = \frac{17}{4} \)
INSERT INTO questions (id, subject, subject_name, track, difficulty, topic, question, options_json, correct_answer, explanation, trap, shortcut_trick, tags_json) VALUES ('m_067', 'math', 'คณิตศาสตร์', 'Gifted', 3, 'เรขาคณิตและพื้นที่แรเงารูปใบไม้ (รูปแบบที่ 67)', 'รูปสี่เหลี่ยมจัตุรัสยาวด้านละ 28 เซนติเมตร มีพื้นที่แรเงารูปใบไม้ตรงกลาง จงหาพื้นที่แรเงา (กำหนด \( \pi = \frac{22}{7} \))', '["448 ตารางเซนติเมตร","462 ตารางเซนติเมตร","434 ตารางเซนติเมตร","392 ตารางเซนติเมตร"]', 0, 'สูตรพื้นที่แรเงารูปใบไม้ในสี่เหลี่ยมจัตุรัส: \( \text{พื้นที่} = \frac{4}{7} \times r^2 = \frac{4}{7} \times 28^2 = 448 \text{ ตร.ซม.} \)', 'รูปใบไม้เกิดจากเซกเตอร์ 2 รูปซ้อนทับกัน', 'สูตรลัดพื้นที่ใบไม้ = (4/7) × ด้าน²', '["เรขาคณิตและพื้นที่แรเงารูปใบไม้ (รูปแบบที่ 67)","Gifted"]');
INSERT INTO questions (id, subject, subject_name, track, difficulty, topic, question, options_json, correct_answer, explanation, trap, shortcut_trick, tags_json) VALUES ('m_068', 'math', 'คณิตศาสตร์', 'Regular', 2, 'การนับและการจับมือแข่งขัน (รูปแบบที่ 68)', 'ในงานเลี้ยงมีคนมาร่วมงาน 74 คน ถ้าทุกคนจับมือทักทายกันครบทุกคน จะเกิดการจับมือทั้งหมดกี่ครั้ง', '["2701 ครั้ง","5402 ครั้ง","2775 ครั้ง","2698 ครั้ง"]', 0, 'ใช้สูตรจับมือ: \( \frac{n(n - 1)}{2} = \frac{74 \times 73}{2} = 2701 \text{ ครั้ง} \)', 'อย่าลืมหาร 2 เพราะจับคู่กัน 1 ครั้งได้ 2 คน', 'สูตรลัดจับมือ: [n × (n - 1)] ÷ 2', '["การนับและการจับมือแข่งขัน (รูปแบบที่ 68)","Regular"]');
INSERT INTO questions (id, subject, subject_name, track, difficulty, topic, question, options_json, correct_answer, explanation, trap, shortcut_trick, tags_json) VALUES ('m_069', 'math', 'คณิตศาสตร์', 'Regular', 2, 'แผนภาพเวนน์-ออยเลอร์และเซต (รูปแบบที่ 69)', 'นักเรียน 178 คน ชอบเรียนคณิตศาสตร์ 89 คน ชอบวิทยาศาสตร์ 87 คน และชอบทั้งสองวิชา 79 คน มีนักเรียนที่ไม่ชอบทั้งสองวิชานี้กี่คน', '["81 คน","85 คน","79 คน","79 คน"]', 0, '1) จำนวนคนที่ชอบอย่างน้อย 1 วิชา = 89 + 87 - 79 = 97 คน
INSERT INTO questions (id, subject, subject_name, track, difficulty, topic, question, options_json, correct_answer, explanation, trap, shortcut_trick, tags_json) VALUES ('m_070', 'math', 'คณิตศาสตร์', 'Gifted', 3, 'อนุกรมเศษส่วนเทเลสโคปิก (รูปแบบที่ 70)', 'จงหาค่าของผลบวก \( \displaystyle \frac{1}{1 \times 2} + \frac{1}{2 \times 3} + \frac{1}{3 \times 4} + ... + \frac{1}{80 \times 81} \)', '["\\( \\displaystyle \\frac{80}{81} \\)","\\( \\displaystyle \\frac{79}{81} \\)","\\( \\displaystyle \\frac{81}{82} \\)","1"]', 0, 'แยกเศษส่วนย่อยตัดกัน: \( (1 - \frac{1}{2}) + (\frac{1}{2} - \frac{1}{3}) + ... + (\frac{1}{80} - \frac{1}{81}) = 1 - \frac{1}{81} = \frac{80}{81} \)', 'พจน์ตรงกลางจะตัดกันหมด เหลือพจน์แรกและพจน์สุดท้าย', 'สูตรลัดเทเลสโคปิก: 1 - 1/(ตัวสุดท้าย)', '["อนุกรมเศษส่วนเทเลสโคปิก (รูปแบบที่ 70)","Gifted"]');
