INSERT INTO questions (id, subject, subject_name, track, difficulty, topic, question, options_json, correct_answer, explanation, trap, shortcut_trick, tags_json) VALUES ('m_137', 'math', 'คณิตศาสตร์', 'Gifted', 3, 'เรขาคณิตและพื้นที่แรเงารูปใบไม้ (รูปแบบที่ 137)', 'รูปสี่เหลี่ยมจัตุรัสยาวด้านละ 14 เซนติเมตร มีพื้นที่แรเงารูปใบไม้ตรงกลาง จงหาพื้นที่แรเงา (กำหนด \( \pi = \frac{22}{7} \))', '["112 ตารางเซนติเมตร","126 ตารางเซนติเมตร","98 ตารางเซนติเมตร","98 ตารางเซนติเมตร"]', 0, 'สูตรพื้นที่แรเงารูปใบไม้ในสี่เหลี่ยมจัตุรัส: \( \text{พื้นที่} = \frac{4}{7} \times r^2 = \frac{4}{7} \times 14^2 = 112 \text{ ตร.ซม.} \)', 'รูปใบไม้เกิดจากเซกเตอร์ 2 รูปซ้อนทับกัน', 'สูตรลัดพื้นที่ใบไม้ = (4/7) × ด้าน²', '["เรขาคณิตและพื้นที่แรเงารูปใบไม้ (รูปแบบที่ 137)","Gifted"]');
INSERT INTO questions (id, subject, subject_name, track, difficulty, topic, question, options_json, correct_answer, explanation, trap, shortcut_trick, tags_json) VALUES ('m_138', 'math', 'คณิตศาสตร์', 'Regular', 2, 'การนับและการจับมือแข่งขัน (รูปแบบที่ 138)', 'ในงานเลี้ยงมีคนมาร่วมงาน 144 คน ถ้าทุกคนจับมือทักทายกันครบทุกคน จะเกิดการจับมือทั้งหมดกี่ครั้ง', '["10296 ครั้ง","20592 ครั้ง","10440 ครั้ง","10293 ครั้ง"]', 0, 'ใช้สูตรจับมือ: \( \frac{n(n - 1)}{2} = \frac{144 \times 143}{2} = 10296 \text{ ครั้ง} \)', 'อย่าลืมหาร 2 เพราะจับคู่กัน 1 ครั้งได้ 2 คน', 'สูตรลัดจับมือ: [n × (n - 1)] ÷ 2', '["การนับและการจับมือแข่งขัน (รูปแบบที่ 138)","Regular"]');
INSERT INTO questions (id, subject, subject_name, track, difficulty, topic, question, options_json, correct_answer, explanation, trap, shortcut_trick, tags_json) VALUES ('m_139', 'math', 'คณิตศาสตร์', 'Regular', 2, 'แผนภาพเวนน์-ออยเลอร์และเซต (รูปแบบที่ 139)', 'นักเรียน 318 คน ชอบเรียนคณิตศาสตร์ 159 คน ชอบวิทยาศาสตร์ 157 คน และชอบทั้งสองวิชา 149 คน มีนักเรียนที่ไม่ชอบทั้งสองวิชานี้กี่คน', '["151 คน","155 คน","149 คน","149 คน"]', 0, '1) จำนวนคนที่ชอบอย่างน้อย 1 วิชา = 159 + 157 - 149 = 167 คน
INSERT INTO questions (id, subject, subject_name, track, difficulty, topic, question, options_json, correct_answer, explanation, trap, shortcut_trick, tags_json) VALUES ('m_140', 'math', 'คณิตศาสตร์', 'Gifted', 3, 'อนุกรมเศษส่วนเทเลสโคปิก (รูปแบบที่ 140)', 'จงหาค่าของผลบวก \( \displaystyle \frac{1}{1 \times 2} + \frac{1}{2 \times 3} + \frac{1}{3 \times 4} + ... + \frac{1}{150 \times 151} \)', '["\\( \\displaystyle \\frac{150}{151} \\)","\\( \\displaystyle \\frac{149}{151} \\)","\\( \\displaystyle \\frac{151}{152} \\)","1"]', 0, 'แยกเศษส่วนย่อยตัดกัน: \( (1 - \frac{1}{2}) + (\frac{1}{2} - \frac{1}{3}) + ... + (\frac{1}{150} - \frac{1}{151}) = 1 - \frac{1}{151} = \frac{150}{151} \)', 'พจน์ตรงกลางจะตัดกันหมด เหลือพจน์แรกและพจน์สุดท้าย', 'สูตรลัดเทเลสโคปิก: 1 - 1/(ตัวสุดท้าย)', '["อนุกรมเศษส่วนเทเลสโคปิก (รูปแบบที่ 140)","Gifted"]');
INSERT INTO questions (id, subject, subject_name, track, difficulty, topic, question, options_json, correct_answer, explanation, trap, shortcut_trick, tags_json) VALUES ('m_141', 'math', 'คณิตศาสตร์', 'Regular', 2, 'สมการขาสัตว์และหัวสัตว์ (รูปแบบที่ 141)', 'ในฟาร์มแห่งหนึ่งมีไก่และกระต่ายรวมกัน 302 ตัว เมื่อนับขารวมกันได้ 898 ขา อยากทราบว่าในฟาร์มนี้มีกระต่ายทั้งหมดกี่ตัว', '["147 ตัว","155 ตัว","149 ตัว","145 ตัว"]', 0, '1) สมมติให้เป็นไก่ทั้งหมด (ตัวละ 2 ขา): มีขา = 302 × 2 = 604 ขา
INSERT INTO questions (id, subject, subject_name, track, difficulty, topic, question, options_json, correct_answer, explanation, trap, shortcut_trick, tags_json) VALUES ('m_142', 'math', 'คณิตศาสตร์', 'Gifted', 3, 'เลขหลักหน่วยของเลขยกกำลัง (รูปแบบที่ 142)', 'เลขหลักหน่วยของผลลัพธ์ \( 9^{2162} \) มีค่าเท่ากับข้อใด', '["1","3","5","7"]', 0, '1) หาคาบวัฏจักรหลักหน่วยของ 9^n: [9, 1, 9, 1] (ซ้ำทุก 4 ตัว)
INSERT INTO questions (id, subject, subject_name, track, difficulty, topic, question, options_json, correct_answer, explanation, trap, shortcut_trick, tags_json) VALUES ('m_143', 'math', 'คณิตศาสตร์', 'Gifted', 3, 'มุมระหว่างเข็มนาฬิกา (รูปแบบที่ 143)', 'เมื่อเวลา 01:05 น. มุมแหลม/มุมป้านขนาดเล็กระหว่างเข็มสั้นและเข็มยาวมีขนาดกี่องศา', '["2.5 องศา","17.5 องศา","17.5 องศา","32.5 องศา"]', 0, 'ใช้สูตรมุมระหว่างเข็มนาฬิกา: \( |30H - 5.5M| = |30(1) - 5.5(5)| = 2.5^\circ \)', 'เข็มสั้นขยับตามเข็มยาวเสมอ (0.5 องศาต่อนาที)', 'สูตรลัด: |30 × ชั่วโมง - 5.5 × นาที|', '["มุมระหว่างเข็มนาฬิกา (รูปแบบที่ 143)","Gifted"]');
INSERT INTO questions (id, subject, subject_name, track, difficulty, topic, question, options_json, correct_answer, explanation, trap, shortcut_trick, tags_json) VALUES ('m_144', 'math', 'คณิตศาสตร์', 'Gifted', 2, 'โจทย์อัตราการทำงานและท่อน้ำ (รูปแบบที่ 144)', 'ท่อ A เปิดน้ำเข้าถังเต็มใน 6 ชั่วโมง ส่วนท่อ B เปิดเต็มใน 4 ชั่วโมง ถ้าเปิดท่อ A และ B พร้อมกัน น้ำจะเต็มถังในเวลากี่ชั่วโมง', '["\\( \\displaystyle \\frac{24}{10} \\) ชั่วโมง","\\( \\displaystyle \\frac{10}{2} \\) ชั่วโมง","\\( \\displaystyle \\frac{26}{10} \\) ชั่วโมง","10 ชั่วโมง"]', 0, '1) ใน 1 ชั่วโมง ท่อ A ทำได้ \( \frac{1}{6} \), ท่อ B ทำได้ \( \frac{1}{4} \)
INSERT INTO questions (id, subject, subject_name, track, difficulty, topic, question, options_json, correct_answer, explanation, trap, shortcut_trick, tags_json) VALUES ('m_145', 'math', 'คณิตศาสตร์', 'Gifted', 3, 'อัตราเร็วเรือพายทวนน้ำ-ตามน้ำ (รูปแบบที่ 145)', 'เรือยนต์แล่นตามน้ำด้วยความเร็ว 170 กม./ชม. และแล่นทวนน้ำด้วยความเร็ว 160 กม./ชม. จงหาความเร็วของกระแสน้ำ', '["5 กิโลเมตรต่อชั่วโมง","165 กิโลเมตรต่อชั่วโมง","7 กิโลเมตรต่อชั่วโมง","9 กิโลเมตรต่อชั่วโมง"]', 0, '1) ความเร็วตามน้ำ = v_เรือ + v_น้ำ = 170
INSERT INTO questions (id, subject, subject_name, track, difficulty, topic, question, options_json, correct_answer, explanation, trap, shortcut_trick, tags_json) VALUES ('m_146', 'math', 'คณิตศาสตร์', 'Gifted', 3, 'เศษส่วนซ้อนหลายชั้น (รูปแบบที่ 146)', 'ถ้า \( \displaystyle x = 3 + \cfrac{1}{4 + \cfrac{1}{4}} \) จงหาค่าของ \( x \) ในรูปเศษส่วนอย่างต่ำ', '["\\( \\displaystyle \\frac{55}{17} \\)","\\( \\displaystyle \\frac{54}{17} \\)","\\( \\displaystyle \\frac{57}{17} \\)","\\( \\displaystyle \\frac{55}{18} \\)"]', 0, '1) ชั้นล่างสุด: \( 4 + \frac{1}{4} = \frac{17}{4} \)
INSERT INTO questions (id, subject, subject_name, track, difficulty, topic, question, options_json, correct_answer, explanation, trap, shortcut_trick, tags_json) VALUES ('m_147', 'math', 'คณิตศาสตร์', 'Gifted', 3, 'เรขาคณิตและพื้นที่แรเงารูปใบไม้ (รูปแบบที่ 147)', 'รูปสี่เหลี่ยมจัตุรัสยาวด้านละ 28 เซนติเมตร มีพื้นที่แรเงารูปใบไม้ตรงกลาง จงหาพื้นที่แรเงา (กำหนด \( \pi = \frac{22}{7} \))', '["448 ตารางเซนติเมตร","462 ตารางเซนติเมตร","434 ตารางเซนติเมตร","392 ตารางเซนติเมตร"]', 0, 'สูตรพื้นที่แรเงารูปใบไม้ในสี่เหลี่ยมจัตุรัส: \( \text{พื้นที่} = \frac{4}{7} \times r^2 = \frac{4}{7} \times 28^2 = 448 \text{ ตร.ซม.} \)', 'รูปใบไม้เกิดจากเซกเตอร์ 2 รูปซ้อนทับกัน', 'สูตรลัดพื้นที่ใบไม้ = (4/7) × ด้าน²', '["เรขาคณิตและพื้นที่แรเงารูปใบไม้ (รูปแบบที่ 147)","Gifted"]');
