INSERT INTO questions (id, subject, subject_name, track, difficulty, topic, question, options_json, correct_answer, explanation, trap, shortcut_trick, tags_json) VALUES ('m_155', 'math', 'คณิตศาสตร์', 'Gifted', 3, 'อัตราเร็วเรือพายทวนน้ำ-ตามน้ำ (รูปแบบที่ 155)', 'เรือยนต์แล่นตามน้ำด้วยความเร็ว 181 กม./ชม. และแล่นทวนน้ำด้วยความเร็ว 169 กม./ชม. จงหาความเร็วของกระแสน้ำ', '["6 กิโลเมตรต่อชั่วโมง","175 กิโลเมตรต่อชั่วโมง","8 กิโลเมตรต่อชั่วโมง","10 กิโลเมตรต่อชั่วโมง"]', 0, '1) ความเร็วตามน้ำ = v_เรือ + v_น้ำ = 181
INSERT INTO questions (id, subject, subject_name, track, difficulty, topic, question, options_json, correct_answer, explanation, trap, shortcut_trick, tags_json) VALUES ('m_156', 'math', 'คณิตศาสตร์', 'Gifted', 3, 'เศษส่วนซ้อนหลายชั้น (รูปแบบที่ 156)', 'ถ้า \( \displaystyle x = 1 + \cfrac{1}{2 + \cfrac{1}{4}} \) จงหาค่าของ \( x \) ในรูปเศษส่วนอย่างต่ำ', '["\\( \\displaystyle \\frac{13}{9} \\)","\\( \\displaystyle \\frac{12}{9} \\)","\\( \\displaystyle \\frac{15}{9} \\)","\\( \\displaystyle \\frac{13}{10} \\)"]', 0, '1) ชั้นล่างสุด: \( 2 + \frac{1}{4} = \frac{9}{4} \)
INSERT INTO questions (id, subject, subject_name, track, difficulty, topic, question, options_json, correct_answer, explanation, trap, shortcut_trick, tags_json) VALUES ('m_157', 'math', 'คณิตศาสตร์', 'Gifted', 3, 'เรขาคณิตและพื้นที่แรเงารูปใบไม้ (รูปแบบที่ 157)', 'รูปสี่เหลี่ยมจัตุรัสยาวด้านละ 14 เซนติเมตร มีพื้นที่แรเงารูปใบไม้ตรงกลาง จงหาพื้นที่แรเงา (กำหนด \( \pi = \frac{22}{7} \))', '["112 ตารางเซนติเมตร","126 ตารางเซนติเมตร","98 ตารางเซนติเมตร","98 ตารางเซนติเมตร"]', 0, 'สูตรพื้นที่แรเงารูปใบไม้ในสี่เหลี่ยมจัตุรัส: \( \text{พื้นที่} = \frac{4}{7} \times r^2 = \frac{4}{7} \times 14^2 = 112 \text{ ตร.ซม.} \)', 'รูปใบไม้เกิดจากเซกเตอร์ 2 รูปซ้อนทับกัน', 'สูตรลัดพื้นที่ใบไม้ = (4/7) × ด้าน²', '["เรขาคณิตและพื้นที่แรเงารูปใบไม้ (รูปแบบที่ 157)","Gifted"]');
INSERT INTO questions (id, subject, subject_name, track, difficulty, topic, question, options_json, correct_answer, explanation, trap, shortcut_trick, tags_json) VALUES ('m_158', 'math', 'คณิตศาสตร์', 'Regular', 2, 'การนับและการจับมือแข่งขัน (รูปแบบที่ 158)', 'ในงานเลี้ยงมีคนมาร่วมงาน 164 คน ถ้าทุกคนจับมือทักทายกันครบทุกคน จะเกิดการจับมือทั้งหมดกี่ครั้ง', '["13366 ครั้ง","26732 ครั้ง","13530 ครั้ง","13363 ครั้ง"]', 0, 'ใช้สูตรจับมือ: \( \frac{n(n - 1)}{2} = \frac{164 \times 163}{2} = 13366 \text{ ครั้ง} \)', 'อย่าลืมหาร 2 เพราะจับคู่กัน 1 ครั้งได้ 2 คน', 'สูตรลัดจับมือ: [n × (n - 1)] ÷ 2', '["การนับและการจับมือแข่งขัน (รูปแบบที่ 158)","Regular"]');
INSERT INTO questions (id, subject, subject_name, track, difficulty, topic, question, options_json, correct_answer, explanation, trap, shortcut_trick, tags_json) VALUES ('m_159', 'math', 'คณิตศาสตร์', 'Regular', 2, 'แผนภาพเวนน์-ออยเลอร์และเซต (รูปแบบที่ 159)', 'นักเรียน 358 คน ชอบเรียนคณิตศาสตร์ 179 คน ชอบวิทยาศาสตร์ 177 คน และชอบทั้งสองวิชา 169 คน มีนักเรียนที่ไม่ชอบทั้งสองวิชานี้กี่คน', '["171 คน","175 คน","169 คน","169 คน"]', 0, '1) จำนวนคนที่ชอบอย่างน้อย 1 วิชา = 179 + 177 - 169 = 187 คน
INSERT INTO questions (id, subject, subject_name, track, difficulty, topic, question, options_json, correct_answer, explanation, trap, shortcut_trick, tags_json) VALUES ('m_160', 'math', 'คณิตศาสตร์', 'Gifted', 3, 'อนุกรมเศษส่วนเทเลสโคปิก (รูปแบบที่ 160)', 'จงหาค่าของผลบวก \( \displaystyle \frac{1}{1 \times 2} + \frac{1}{2 \times 3} + \frac{1}{3 \times 4} + ... + \frac{1}{170 \times 171} \)', '["\\( \\displaystyle \\frac{170}{171} \\)","\\( \\displaystyle \\frac{169}{171} \\)","\\( \\displaystyle \\frac{171}{172} \\)","1"]', 0, 'แยกเศษส่วนย่อยตัดกัน: \( (1 - \frac{1}{2}) + (\frac{1}{2} - \frac{1}{3}) + ... + (\frac{1}{170} - \frac{1}{171}) = 1 - \frac{1}{171} = \frac{170}{171} \)', 'พจน์ตรงกลางจะตัดกันหมด เหลือพจน์แรกและพจน์สุดท้าย', 'สูตรลัดเทเลสโคปิก: 1 - 1/(ตัวสุดท้าย)', '["อนุกรมเศษส่วนเทเลสโคปิก (รูปแบบที่ 160)","Gifted"]');
INSERT INTO questions (id, subject, subject_name, track, difficulty, topic, question, options_json, correct_answer, explanation, trap, shortcut_trick, tags_json) VALUES ('m_161', 'math', 'คณิตศาสตร์', 'Regular', 2, 'สมการขาสัตว์และหัวสัตว์ (รูปแบบที่ 161)', 'ในฟาร์มแห่งหนึ่งมีไก่และกระต่ายรวมกัน 342 ตัว เมื่อนับขารวมกันได้ 1018 ขา อยากทราบว่าในฟาร์มนี้มีกระต่ายทั้งหมดกี่ตัว', '["167 ตัว","175 ตัว","169 ตัว","165 ตัว"]', 0, '1) สมมติให้เป็นไก่ทั้งหมด (ตัวละ 2 ขา): มีขา = 342 × 2 = 684 ขา
INSERT INTO questions (id, subject, subject_name, track, difficulty, topic, question, options_json, correct_answer, explanation, trap, shortcut_trick, tags_json) VALUES ('m_162', 'math', 'คณิตศาสตร์', 'Gifted', 3, 'เลขหลักหน่วยของเลขยกกำลัง (รูปแบบที่ 162)', 'เลขหลักหน่วยของผลลัพธ์ \( 7^{2182} \) มีค่าเท่ากับข้อใด', '["9","1","3","5"]', 0, '1) หาคาบวัฏจักรหลักหน่วยของ 7^n: [7, 9, 3, 1] (ซ้ำทุก 4 ตัว)
INSERT INTO questions (id, subject, subject_name, track, difficulty, topic, question, options_json, correct_answer, explanation, trap, shortcut_trick, tags_json) VALUES ('m_163', 'math', 'คณิตศาสตร์', 'Gifted', 3, 'มุมระหว่างเข็มนาฬิกา (รูปแบบที่ 163)', 'เมื่อเวลา 10:50 น. มุมแหลม/มุมป้านขนาดเล็กระหว่างเข็มสั้นและเข็มยาวมีขนาดกี่องศา', '["25 องศา","40 องศา","5 องศา","55 องศา"]', 0, 'ใช้สูตรมุมระหว่างเข็มนาฬิกา: \( |30H - 5.5M| = |30(10) - 5.5(50)| = 25^\circ \)', 'เข็มสั้นขยับตามเข็มยาวเสมอ (0.5 องศาต่อนาที)', 'สูตรลัด: |30 × ชั่วโมง - 5.5 × นาที|', '["มุมระหว่างเข็มนาฬิกา (รูปแบบที่ 163)","Gifted"]');
INSERT INTO questions (id, subject, subject_name, track, difficulty, topic, question, options_json, correct_answer, explanation, trap, shortcut_trick, tags_json) VALUES ('m_164', 'math', 'คณิตศาสตร์', 'Gifted', 2, 'โจทย์อัตราการทำงานและท่อน้ำ (รูปแบบที่ 164)', 'ท่อ A เปิดน้ำเข้าถังเต็มใน 6 ชั่วโมง ส่วนท่อ B เปิดเต็มใน 6 ชั่วโมง ถ้าเปิดท่อ A และ B พร้อมกัน น้ำจะเต็มถังในเวลากี่ชั่วโมง', '["\\( \\displaystyle \\frac{36}{12} \\) ชั่วโมง","\\( \\displaystyle \\frac{12}{2} \\) ชั่วโมง","\\( \\displaystyle \\frac{38}{12} \\) ชั่วโมง","12 ชั่วโมง"]', 0, '1) ใน 1 ชั่วโมง ท่อ A ทำได้ \( \frac{1}{6} \), ท่อ B ทำได้ \( \frac{1}{6} \)
INSERT INTO questions (id, subject, subject_name, track, difficulty, topic, question, options_json, correct_answer, explanation, trap, shortcut_trick, tags_json) VALUES ('m_165', 'math', 'คณิตศาสตร์', 'Gifted', 3, 'อัตราเร็วเรือพายทวนน้ำ-ตามน้ำ (รูปแบบที่ 165)', 'เรือยนต์แล่นตามน้ำด้วยความเร็ว 189 กม./ชม. และแล่นทวนน้ำด้วยความเร็ว 181 กม./ชม. จงหาความเร็วของกระแสน้ำ', '["4 กิโลเมตรต่อชั่วโมง","185 กิโลเมตรต่อชั่วโมง","6 กิโลเมตรต่อชั่วโมง","8 กิโลเมตรต่อชั่วโมง"]', 0, '1) ความเร็วตามน้ำ = v_เรือ + v_น้ำ = 189
