INSERT INTO questions (id, subject, subject_name, track, difficulty, topic, question, options_json, correct_answer, explanation, trap, shortcut_trick, tags_json) VALUES ('m_174', 'math', 'คณิตศาสตร์', 'Gifted', 2, 'โจทย์อัตราการทำงานและท่อน้ำ (รูปแบบที่ 174)', 'ท่อ A เปิดน้ำเข้าถังเต็มใน 6 ชั่วโมง ส่วนท่อ B เปิดเต็มใน 4 ชั่วโมง ถ้าเปิดท่อ A และ B พร้อมกัน น้ำจะเต็มถังในเวลากี่ชั่วโมง', '["\\( \\displaystyle \\frac{24}{10} \\) ชั่วโมง","\\( \\displaystyle \\frac{10}{2} \\) ชั่วโมง","\\( \\displaystyle \\frac{26}{10} \\) ชั่วโมง","10 ชั่วโมง"]', 0, '1) ใน 1 ชั่วโมง ท่อ A ทำได้ \( \frac{1}{6} \), ท่อ B ทำได้ \( \frac{1}{4} \)
INSERT INTO questions (id, subject, subject_name, track, difficulty, topic, question, options_json, correct_answer, explanation, trap, shortcut_trick, tags_json) VALUES ('m_175', 'math', 'คณิตศาสตร์', 'Gifted', 3, 'อัตราเร็วเรือพายทวนน้ำ-ตามน้ำ (รูปแบบที่ 175)', 'เรือยนต์แล่นตามน้ำด้วยความเร็ว 200 กม./ชม. และแล่นทวนน้ำด้วยความเร็ว 190 กม./ชม. จงหาความเร็วของกระแสน้ำ', '["5 กิโลเมตรต่อชั่วโมง","195 กิโลเมตรต่อชั่วโมง","7 กิโลเมตรต่อชั่วโมง","9 กิโลเมตรต่อชั่วโมง"]', 0, '1) ความเร็วตามน้ำ = v_เรือ + v_น้ำ = 200
INSERT INTO questions (id, subject, subject_name, track, difficulty, topic, question, options_json, correct_answer, explanation, trap, shortcut_trick, tags_json) VALUES ('m_176', 'math', 'คณิตศาสตร์', 'Gifted', 3, 'เศษส่วนซ้อนหลายชั้น (รูปแบบที่ 176)', 'ถ้า \( \displaystyle x = 3 + \cfrac{1}{2 + \cfrac{1}{4}} \) จงหาค่าของ \( x \) ในรูปเศษส่วนอย่างต่ำ', '["\\( \\displaystyle \\frac{31}{9} \\)","\\( \\displaystyle \\frac{30}{9} \\)","\\( \\displaystyle \\frac{33}{9} \\)","\\( \\displaystyle \\frac{31}{10} \\)"]', 0, '1) ชั้นล่างสุด: \( 2 + \frac{1}{4} = \frac{9}{4} \)
INSERT INTO questions (id, subject, subject_name, track, difficulty, topic, question, options_json, correct_answer, explanation, trap, shortcut_trick, tags_json) VALUES ('m_177', 'math', 'คณิตศาสตร์', 'Gifted', 3, 'เรขาคณิตและพื้นที่แรเงารูปใบไม้ (รูปแบบที่ 177)', 'รูปสี่เหลี่ยมจัตุรัสยาวด้านละ 14 เซนติเมตร มีพื้นที่แรเงารูปใบไม้ตรงกลาง จงหาพื้นที่แรเงา (กำหนด \( \pi = \frac{22}{7} \))', '["112 ตารางเซนติเมตร","126 ตารางเซนติเมตร","98 ตารางเซนติเมตร","98 ตารางเซนติเมตร"]', 0, 'สูตรพื้นที่แรเงารูปใบไม้ในสี่เหลี่ยมจัตุรัส: \( \text{พื้นที่} = \frac{4}{7} \times r^2 = \frac{4}{7} \times 14^2 = 112 \text{ ตร.ซม.} \)', 'รูปใบไม้เกิดจากเซกเตอร์ 2 รูปซ้อนทับกัน', 'สูตรลัดพื้นที่ใบไม้ = (4/7) × ด้าน²', '["เรขาคณิตและพื้นที่แรเงารูปใบไม้ (รูปแบบที่ 177)","Gifted"]');
INSERT INTO questions (id, subject, subject_name, track, difficulty, topic, question, options_json, correct_answer, explanation, trap, shortcut_trick, tags_json) VALUES ('m_178', 'math', 'คณิตศาสตร์', 'Regular', 2, 'การนับและการจับมือแข่งขัน (รูปแบบที่ 178)', 'ในงานเลี้ยงมีคนมาร่วมงาน 184 คน ถ้าทุกคนจับมือทักทายกันครบทุกคน จะเกิดการจับมือทั้งหมดกี่ครั้ง', '["16836 ครั้ง","33672 ครั้ง","17020 ครั้ง","16833 ครั้ง"]', 0, 'ใช้สูตรจับมือ: \( \frac{n(n - 1)}{2} = \frac{184 \times 183}{2} = 16836 \text{ ครั้ง} \)', 'อย่าลืมหาร 2 เพราะจับคู่กัน 1 ครั้งได้ 2 คน', 'สูตรลัดจับมือ: [n × (n - 1)] ÷ 2', '["การนับและการจับมือแข่งขัน (รูปแบบที่ 178)","Regular"]');
INSERT INTO questions (id, subject, subject_name, track, difficulty, topic, question, options_json, correct_answer, explanation, trap, shortcut_trick, tags_json) VALUES ('m_179', 'math', 'คณิตศาสตร์', 'Regular', 2, 'แผนภาพเวนน์-ออยเลอร์และเซต (รูปแบบที่ 179)', 'นักเรียน 398 คน ชอบเรียนคณิตศาสตร์ 199 คน ชอบวิทยาศาสตร์ 197 คน และชอบทั้งสองวิชา 189 คน มีนักเรียนที่ไม่ชอบทั้งสองวิชานี้กี่คน', '["191 คน","195 คน","189 คน","189 คน"]', 0, '1) จำนวนคนที่ชอบอย่างน้อย 1 วิชา = 199 + 197 - 189 = 207 คน
INSERT INTO questions (id, subject, subject_name, track, difficulty, topic, question, options_json, correct_answer, explanation, trap, shortcut_trick, tags_json) VALUES ('m_180', 'math', 'คณิตศาสตร์', 'Gifted', 3, 'อนุกรมเศษส่วนเทเลสโคปิก (รูปแบบที่ 180)', 'จงหาค่าของผลบวก \( \displaystyle \frac{1}{1 \times 2} + \frac{1}{2 \times 3} + \frac{1}{3 \times 4} + ... + \frac{1}{190 \times 191} \)', '["\\( \\displaystyle \\frac{190}{191} \\)","\\( \\displaystyle \\frac{189}{191} \\)","\\( \\displaystyle \\frac{191}{192} \\)","1"]', 0, 'แยกเศษส่วนย่อยตัดกัน: \( (1 - \frac{1}{2}) + (\frac{1}{2} - \frac{1}{3}) + ... + (\frac{1}{190} - \frac{1}{191}) = 1 - \frac{1}{191} = \frac{190}{191} \)', 'พจน์ตรงกลางจะตัดกันหมด เหลือพจน์แรกและพจน์สุดท้าย', 'สูตรลัดเทเลสโคปิก: 1 - 1/(ตัวสุดท้าย)', '["อนุกรมเศษส่วนเทเลสโคปิก (รูปแบบที่ 180)","Gifted"]');
INSERT INTO questions (id, subject, subject_name, track, difficulty, topic, question, options_json, correct_answer, explanation, trap, shortcut_trick, tags_json) VALUES ('m_181', 'math', 'คณิตศาสตร์', 'Regular', 2, 'สมการขาสัตว์และหัวสัตว์ (รูปแบบที่ 181)', 'ในฟาร์มแห่งหนึ่งมีไก่และกระต่ายรวมกัน 382 ตัว เมื่อนับขารวมกันได้ 1138 ขา อยากทราบว่าในฟาร์มนี้มีกระต่ายทั้งหมดกี่ตัว', '["187 ตัว","195 ตัว","189 ตัว","185 ตัว"]', 0, '1) สมมติให้เป็นไก่ทั้งหมด (ตัวละ 2 ขา): มีขา = 382 × 2 = 764 ขา
INSERT INTO questions (id, subject, subject_name, track, difficulty, topic, question, options_json, correct_answer, explanation, trap, shortcut_trick, tags_json) VALUES ('m_182', 'math', 'คณิตศาสตร์', 'Gifted', 3, 'เลขหลักหน่วยของเลขยกกำลัง (รูปแบบที่ 182)', 'เลขหลักหน่วยของผลลัพธ์ \( 2^{2202} \) มีค่าเท่ากับข้อใด', '["4","6","8","0"]', 0, '1) หาคาบวัฏจักรหลักหน่วยของ 2^n: [2, 4, 8, 6] (ซ้ำทุก 4 ตัว)
