INSERT INTO questions (id, subject, subject_name, track, difficulty, topic, question, options_json, correct_answer, explanation, trap, shortcut_trick, tags_json) VALUES ('m_193', 'math', 'คณิตศาสตร์', 'Gifted', 3, 'มุมระหว่างเข็มนาฬิกา (รูปแบบที่ 193)', 'เมื่อเวลา 07:35 น. มุมแหลม/มุมป้านขนาดเล็กระหว่างเข็มสั้นและเข็มยาวมีขนาดกี่องศา', '["17.5 องศา","32.5 องศา","2.5 องศา","47.5 องศา"]', 0, 'ใช้สูตรมุมระหว่างเข็มนาฬิกา: \( |30H - 5.5M| = |30(7) - 5.5(35)| = 17.5^\circ \)', 'เข็มสั้นขยับตามเข็มยาวเสมอ (0.5 องศาต่อนาที)', 'สูตรลัด: |30 × ชั่วโมง - 5.5 × นาที|', '["มุมระหว่างเข็มนาฬิกา (รูปแบบที่ 193)","Gifted"]');
INSERT INTO questions (id, subject, subject_name, track, difficulty, topic, question, options_json, correct_answer, explanation, trap, shortcut_trick, tags_json) VALUES ('m_194', 'math', 'คณิตศาสตร์', 'Gifted', 2, 'โจทย์อัตราการทำงานและท่อน้ำ (รูปแบบที่ 194)', 'ท่อ A เปิดน้ำเข้าถังเต็มใน 6 ชั่วโมง ส่วนท่อ B เปิดเต็มใน 6 ชั่วโมง ถ้าเปิดท่อ A และ B พร้อมกัน น้ำจะเต็มถังในเวลากี่ชั่วโมง', '["\\( \\displaystyle \\frac{36}{12} \\) ชั่วโมง","\\( \\displaystyle \\frac{12}{2} \\) ชั่วโมง","\\( \\displaystyle \\frac{38}{12} \\) ชั่วโมง","12 ชั่วโมง"]', 0, '1) ใน 1 ชั่วโมง ท่อ A ทำได้ \( \frac{1}{6} \), ท่อ B ทำได้ \( \frac{1}{6} \)
INSERT INTO questions (id, subject, subject_name, track, difficulty, topic, question, options_json, correct_answer, explanation, trap, shortcut_trick, tags_json) VALUES ('m_195', 'math', 'คณิตศาสตร์', 'Gifted', 3, 'อัตราเร็วเรือพายทวนน้ำ-ตามน้ำ (รูปแบบที่ 195)', 'เรือยนต์แล่นตามน้ำด้วยความเร็ว 219 กม./ชม. และแล่นทวนน้ำด้วยความเร็ว 211 กม./ชม. จงหาความเร็วของกระแสน้ำ', '["4 กิโลเมตรต่อชั่วโมง","215 กิโลเมตรต่อชั่วโมง","6 กิโลเมตรต่อชั่วโมง","8 กิโลเมตรต่อชั่วโมง"]', 0, '1) ความเร็วตามน้ำ = v_เรือ + v_น้ำ = 219
INSERT INTO questions (id, subject, subject_name, track, difficulty, topic, question, options_json, correct_answer, explanation, trap, shortcut_trick, tags_json) VALUES ('m_196', 'math', 'คณิตศาสตร์', 'Gifted', 3, 'เศษส่วนซ้อนหลายชั้น (รูปแบบที่ 196)', 'ถ้า \( \displaystyle x = 2 + \cfrac{1}{2 + \cfrac{1}{4}} \) จงหาค่าของ \( x \) ในรูปเศษส่วนอย่างต่ำ', '["\\( \\displaystyle \\frac{22}{9} \\)","\\( \\displaystyle \\frac{21}{9} \\)","\\( \\displaystyle \\frac{24}{9} \\)","\\( \\displaystyle \\frac{22}{10} \\)"]', 0, '1) ชั้นล่างสุด: \( 2 + \frac{1}{4} = \frac{9}{4} \)
INSERT INTO questions (id, subject, subject_name, track, difficulty, topic, question, options_json, correct_answer, explanation, trap, shortcut_trick, tags_json) VALUES ('m_197', 'math', 'คณิตศาสตร์', 'Gifted', 3, 'เรขาคณิตและพื้นที่แรเงารูปใบไม้ (รูปแบบที่ 197)', 'รูปสี่เหลี่ยมจัตุรัสยาวด้านละ 14 เซนติเมตร มีพื้นที่แรเงารูปใบไม้ตรงกลาง จงหาพื้นที่แรเงา (กำหนด \( \pi = \frac{22}{7} \))', '["112 ตารางเซนติเมตร","126 ตารางเซนติเมตร","98 ตารางเซนติเมตร","98 ตารางเซนติเมตร"]', 0, 'สูตรพื้นที่แรเงารูปใบไม้ในสี่เหลี่ยมจัตุรัส: \( \text{พื้นที่} = \frac{4}{7} \times r^2 = \frac{4}{7} \times 14^2 = 112 \text{ ตร.ซม.} \)', 'รูปใบไม้เกิดจากเซกเตอร์ 2 รูปซ้อนทับกัน', 'สูตรลัดพื้นที่ใบไม้ = (4/7) × ด้าน²', '["เรขาคณิตและพื้นที่แรเงารูปใบไม้ (รูปแบบที่ 197)","Gifted"]');
INSERT INTO questions (id, subject, subject_name, track, difficulty, topic, question, options_json, correct_answer, explanation, trap, shortcut_trick, tags_json) VALUES ('m_198', 'math', 'คณิตศาสตร์', 'Regular', 2, 'การนับและการจับมือแข่งขัน (รูปแบบที่ 198)', 'ในงานเลี้ยงมีคนมาร่วมงาน 204 คน ถ้าทุกคนจับมือทักทายกันครบทุกคน จะเกิดการจับมือทั้งหมดกี่ครั้ง', '["20706 ครั้ง","41412 ครั้ง","20910 ครั้ง","20703 ครั้ง"]', 0, 'ใช้สูตรจับมือ: \( \frac{n(n - 1)}{2} = \frac{204 \times 203}{2} = 20706 \text{ ครั้ง} \)', 'อย่าลืมหาร 2 เพราะจับคู่กัน 1 ครั้งได้ 2 คน', 'สูตรลัดจับมือ: [n × (n - 1)] ÷ 2', '["การนับและการจับมือแข่งขัน (รูปแบบที่ 198)","Regular"]');
INSERT INTO questions (id, subject, subject_name, track, difficulty, topic, question, options_json, correct_answer, explanation, trap, shortcut_trick, tags_json) VALUES ('m_199', 'math', 'คณิตศาสตร์', 'Regular', 2, 'แผนภาพเวนน์-ออยเลอร์และเซต (รูปแบบที่ 199)', 'นักเรียน 438 คน ชอบเรียนคณิตศาสตร์ 219 คน ชอบวิทยาศาสตร์ 217 คน และชอบทั้งสองวิชา 209 คน มีนักเรียนที่ไม่ชอบทั้งสองวิชานี้กี่คน', '["211 คน","215 คน","209 คน","209 คน"]', 0, '1) จำนวนคนที่ชอบอย่างน้อย 1 วิชา = 219 + 217 - 209 = 227 คน
INSERT INTO questions (id, subject, subject_name, track, difficulty, topic, question, options_json, correct_answer, explanation, trap, shortcut_trick, tags_json) VALUES ('m_200', 'math', 'คณิตศาสตร์', 'Gifted', 3, 'อนุกรมเศษส่วนเทเลสโคปิก (รูปแบบที่ 200)', 'จงหาค่าของผลบวก \( \displaystyle \frac{1}{1 \times 2} + \frac{1}{2 \times 3} + \frac{1}{3 \times 4} + ... + \frac{1}{210 \times 211} \)', '["\\( \\displaystyle \\frac{210}{211} \\)","\\( \\displaystyle \\frac{209}{211} \\)","\\( \\displaystyle \\frac{211}{212} \\)","1"]', 0, 'แยกเศษส่วนย่อยตัดกัน: \( (1 - \frac{1}{2}) + (\frac{1}{2} - \frac{1}{3}) + ... + (\frac{1}{210} - \frac{1}{211}) = 1 - \frac{1}{211} = \frac{210}{211} \)', 'พจน์ตรงกลางจะตัดกันหมด เหลือพจน์แรกและพจน์สุดท้าย', 'สูตรลัดเทเลสโคปิก: 1 - 1/(ตัวสุดท้าย)', '["อนุกรมเศษส่วนเทเลสโคปิก (รูปแบบที่ 200)","Gifted"]');
INSERT INTO questions (id, subject, subject_name, track, difficulty, topic, question, options_json, correct_answer, explanation, trap, shortcut_trick, tags_json) VALUES ('s_001', 'science', 'วิทยาศาสตร์', 'Regular', 2, 'การทดสอบสารอาหารและอินดิเคเตอร์ (ข้อที่ 1)', 'เมื่อหยดสารละลายเบเนดิกต์ลงในอาหารแล้วต้ม เกิดตะกอนสีส้มอิฐ แสดงว่ามีสารใด (ข้อสอบชุดมาตรฐานที่ 1)', '["น้ำตาลโมเลกุลเดี่ยว (เช่น กลูโคส)","แป้งและคาร์โบไฮเดรตเชิงซ้อน","โปรตีน","ไขมัน"]', 0, 'เบเนดิกต์ + ความร้อน ทำปฏิกิริยากับน้ำตาลรีดิวซ์เกิดตะกอนสีส้มอิฐ', 'วิเคราะห์หลักวิทยาศาสตร์และการทดลอง', 'จำคอนเซ็ปต์และตัวแปรควบคุม', '["การทดสอบสารอาหารและอินดิเคเตอร์ (ข้อที่ 1)","Regular"]');
INSERT INTO questions (id, subject, subject_name, track, difficulty, topic, question, options_json, correct_answer, explanation, trap, shortcut_trick, tags_json) VALUES ('s_002', 'science', 'วิทยาศาสตร์', 'Gifted', 3, 'ชีววิทยาของพืช: ท่อลำเลียง (ข้อที่ 2)', 'ท่อลำเลียง โฟลเอ็ม (Phloem) ในพืชทำหน้าที่และมีทิศทางอย่างไร (ข้อสอบชุดมาตรฐานที่ 2)', '["ลำเลียงอาหารจากใบไปทั่วทุกส่วนได้ทุกทิศทาง","ลำเลียงน้ำจากรากขึ้นบนเท่านั้น","ลำเลียงแก๊สออกซิเจน","ลำเลียงแร่ธาตุลงล่างอย่างเดียว"]', 0, 'ไซเลมลำเลียงน้ำขึ้นบน ส่วนโฟลเอ็มลำเลียงอาหารได้ทุกทิศทาง', 'วิเคราะห์หลักวิทยาศาสตร์และการทดลอง', 'จำคอนเซ็ปต์และตัวแปรควบคุม', '["ชีววิทยาของพืช: ท่อลำเลียง (ข้อที่ 2)","Gifted"]');
INSERT INTO questions (id, subject, subject_name, track, difficulty, topic, question, options_json, correct_answer, explanation, trap, shortcut_trick, tags_json) VALUES ('s_003', 'science', 'วิทยาศาสตร์', 'Regular', 1, 'พันธุศาสตร์และหมู่เลือด ABO (ข้อที่ 3)', 'พ่อเลือดหมู่ A (IA i) แม่เลือดหมู่ B (IB i) ลูกมีโอกาสเลือดหมู่ใดบ้าง (ข้อสอบชุดมาตรฐานที่ 3)', '["มีโอกาสเป็นได้ทั้ง 4 หมู่ (A, B, AB, O)","หมู่ AB เท่านั้น","หมู่ A และ B เท่านั้น","ไม่มีโอกาสเป็นหมู่ O"]', 0, 'การจับคู่ยีน IA, IB, i ทำให้เกิดจีโนไทป์ IAIB, IAi, IBi, ii ครบทั้ง 4 หมู่', 'วิเคราะห์หลักวิทยาศาสตร์และการทดลอง', 'จำคอนเซ็ปต์และตัวแปรควบคุม', '["พันธุศาสตร์และหมู่เลือด ABO (ข้อที่ 3)","Regular"]');
INSERT INTO questions (id, subject, subject_name, track, difficulty, topic, question, options_json, correct_answer, explanation, trap, shortcut_trick, tags_json) VALUES ('s_004', 'science', 'วิทยาศาสตร์', 'Gifted', 2, 'ฟิสิกส์: เครื่องกลอย่างง่าย (รอกเดี่ยว) (ข้อที่ 4)', 'การใช้ รอกเดี่ยวเคลื่อนที่ ยกวัตถุหนัก 600 นิวตัน จะต้องออกแรงดึงกี่นิวตัน (ข้อสอบชุดมาตรฐานที่ 4)', '["300 นิวตัน (ผ่อนแรงได้ครึ่งหนึ่ง)","600 นิวตัน (ไม่ผ่อนแรง)","150 นิวตัน","1,200 นิวตัน"]', 0, 'รอกเดี่ยวเคลื่อนที่ช่วยผ่อนแรง 2 เท่า: F = W/2 = 600/2 = 300 N', 'วิเคราะห์หลักวิทยาศาสตร์และการทดลอง', 'จำคอนเซ็ปต์และตัวแปรควบคุม', '["ฟิสิกส์: เครื่องกลอย่างง่าย (รอกเดี่ยว) (ข้อที่ 4)","Gifted"]');
INSERT INTO questions (id, subject, subject_name, track, difficulty, topic, question, options_json, correct_answer, explanation, trap, shortcut_trick, tags_json) VALUES ('s_005', 'science', 'วิทยาศาสตร์', 'Regular', 3, 'ดาราศาสตร์: เฟสดวงจันทร์ (ข้อที่ 5)', 'ในวัน แรม 8 ค่ำ ดวงจันทร์จะปรากฏสว่างด้านใดและขึ้นเวลาใด (ข้อสอบชุดมาตรฐานที่ 5)', '["สว่างครึ่งดวงด้านซ้าย (ทิศตะวันออก) และขึ้นเวลาเที่ยงคืน","สว่างครึ่งดวงด้านขวา และขึ้นเวลาเที่ยงวัน","สว่างเต็มดวง","มืดสนิททั้งดวง"]', 0, 'ข้างแรมดวงจันทร์หันด้านสว่างไปทางซ้าย (ทิศตะวันออก) และขึ้นเวลา 24:00 น.', 'วิเคราะห์หลักวิทยาศาสตร์และการทดลอง', 'จำคอนเซ็ปต์และตัวแปรควบคุม', '["ดาราศาสตร์: เฟสดวงจันทร์ (ข้อที่ 5)","Regular"]');
INSERT INTO questions (id, subject, subject_name, track, difficulty, topic, question, options_json, correct_answer, explanation, trap, shortcut_trick, tags_json) VALUES ('s_006', 'science', 'วิทยาศาสตร์', 'Gifted', 1, 'เคมี: การทดสอบกรด-เบส (ข้อที่ 6)', 'สารละลายที่เปลี่ยนสีกระดาษลิตมัสจากแดงเป็นน้ำเงิน และฟีนอล์ฟทาลีนเป็นสีชมพู คือสารใด (ข้อสอบชุดมาตรฐานที่ 6)', '["สารละลายเบส (เช่น น้ำขี้เถ้า น้ำสบู่)","สารละลายกรด (เช่น น้ำมะนาว)","สารละลายเกลือบริสุทธิ์ (กลาง)","น้ำกลั่น"]', 0, 'เบสเปลี่ยนลิตมัสแดงเป็นน้ำเงิน และทำให้ฟีนอล์ฟทาลีนเปลี่ยนเป็นสีชมพู', 'วิเคราะห์หลักวิทยาศาสตร์และการทดลอง', 'จำคอนเซ็ปต์และตัวแปรควบคุม', '["เคมี: การทดสอบกรด-เบส (ข้อที่ 6)","Gifted"]');
INSERT INTO questions (id, subject, subject_name, track, difficulty, topic, question, options_json, correct_answer, explanation, trap, shortcut_trick, tags_json) VALUES ('s_007', 'science', 'วิทยาศาสตร์', 'Regular', 2, 'ธรณีวิทยา: วัฏจักรของหิน (ข้อที่ 7)', 'หินแกรนิตเมื่อถูกความร้อนและความดันสูงใต้โลกจะแปรสภาพเป็นหินชนิดใด (ข้อสอบชุดมาตรฐานที่ 7)', '["หินไนส์ (Gneiss)","หินอ่อน","หินชนวน","หินควอร์ตไซต์"]', 0, 'หินแกรนิต (อัคนี) แปรเป็นหินไนส์ ส่วนหินปูนแปรเป็นหินอ่อน', 'วิเคราะห์หลักวิทยาศาสตร์และการทดลอง', 'จำคอนเซ็ปต์และตัวแปรควบคุม', '["ธรณีวิทยา: วัฏจักรของหิน (ข้อที่ 7)","Regular"]');
INSERT INTO questions (id, subject, subject_name, track, difficulty, topic, question, options_json, correct_answer, explanation, trap, shortcut_trick, tags_json) VALUES ('s_008', 'science', 'วิทยาศาสตร์', 'Gifted', 3, 'ฟิสิกส์: การถ่ายโอนความร้อน (ข้อที่ 8)', 'ความร้อนจากดวงอาทิตย์เดินทางผ่านสุญญากาศในอวกาศมายังโลกโดยวิธีใด (ข้อสอบชุดมาตรฐานที่ 8)', '["การแผ่รังสีความร้อน (Radiation)","การพาความร้อน (Convection)","การนำความร้อน (Conduction)","การพาและการนำ"]', 0, 'การแผ่รังสีความร้อนไม่ต้องอาศัยตัวกลาง สามารถเดินทางผ่านสุญญากาศได้', 'วิเคราะห์หลักวิทยาศาสตร์และการทดลอง', 'จำคอนเซ็ปต์และตัวแปรควบคุม', '["ฟิสิกส์: การถ่ายโอนความร้อน (ข้อที่ 8)","Gifted"]');
INSERT INTO questions (id, subject, subject_name, track, difficulty, topic, question, options_json, correct_answer, explanation, trap, shortcut_trick, tags_json) VALUES ('s_009', 'science', 'วิทยาศาสตร์', 'Regular', 1, 'นิเวศวิทยา: ภาวะความสัมพันธ์ (ข้อที่ 9)', 'ความสัมพันธ์ระหว่าง ผึ้งกับดอกไม้ จัดเป็นภาวะความสัมพันธ์แบบใด (ข้อสอบชุดมาตรฐานที่ 9)', '["ภาวะได้ประโยชน์ร่วมกัน (+/+)","ภาวะพึ่งพากัน","ภาวะอิงอาศัย (+/0)","ภาวะปรสิต (+/-)"]', 0, 'ผึ้งได้น้ำหวาน ดอกไม้ได้ผสมเกสร แยกกันอยู่ได้ เป็นภาวะได้ประโยชน์ร่วมกัน', 'วิเคราะห์หลักวิทยาศาสตร์และการทดลอง', 'จำคอนเซ็ปต์และตัวแปรควบคุม', '["นิเวศวิทยา: ภาวะความสัมพันธ์ (ข้อที่ 9)","Regular"]');
INSERT INTO questions (id, subject, subject_name, track, difficulty, topic, question, options_json, correct_answer, explanation, trap, shortcut_trick, tags_json) VALUES ('s_010', 'science', 'วิทยาศาสตร์', 'Gifted', 2, 'ฟิสิกส์: กระจกและเลนส์ (ข้อที่ 10)', 'กระจกที่ติดตามทางโค้งเพื่อช่วยให้มองเห็นมุมมองได้กว้างขึ้นคือกระจกชนิดใด (ข้อสอบชุดมาตรฐานที่ 10)', '["กระจกนูน (Convex Mirror)","กระจกเว้า (Concave Mirror)","กระจกเงาราบ","เลนส์เว้า"]', 0, 'กระจกนูนให้ภาพเสมือนหัวตั้งขนาดเล็กกว่าวัตถุ ช่วยขยายลานสายตาให้กว้างขึ้น', 'วิเคราะห์หลักวิทยาศาสตร์และการทดลอง', 'จำคอนเซ็ปต์และตัวแปรควบคุม', '["ฟิสิกส์: กระจกและเลนส์ (ข้อที่ 10)","Gifted"]');
INSERT INTO questions (id, subject, subject_name, track, difficulty, topic, question, options_json, correct_answer, explanation, trap, shortcut_trick, tags_json) VALUES ('s_011', 'science', 'วิทยาศาสตร์', 'Regular', 3, 'ระบบร่างกาย: การย่อยอาหาร (ข้อที่ 11)', 'อวัยวะใดทำหน้าที่ดูดซึมสารอาหารส่วนใหญ่เข้าสู่กระแสเลือด (ข้อสอบชุดมาตรฐานที่ 11)', '["ลำไส้เล็ก (Small Intestine)","กระเพาะอาหาร","ลำไส้ใหญ่","หลอดอาหาร"]', 0, 'ลำไส้เล็กมีวิลไล (Villi) ช่วยเพิ่มพื้นที่ผิวในการดูดซึมสารอาหารเกือบทั้งหมด', 'วิเคราะห์หลักวิทยาศาสตร์และการทดลอง', 'จำคอนเซ็ปต์และตัวแปรควบคุม', '["ระบบร่างกาย: การย่อยอาหาร (ข้อที่ 11)","Regular"]');
INSERT INTO questions (id, subject, subject_name, track, difficulty, topic, question, options_json, correct_answer, explanation, trap, shortcut_trick, tags_json) VALUES ('s_012', 'science', 'วิทยาศาสตร์', 'Gifted', 1, 'ไฟฟ้า: วงจรไฟฟ้า (ข้อที่ 12)', 'การต่อหลอดไฟฟ้าแบบขนานในบ้านมีข้อดีอย่างไรเมื่อเทียบกับแบบอนุกรม (ข้อสอบชุดมาตรฐานที่ 12)', '["ถ้าหลอดหนึ่งขาด หลอดอื่นยังคงสว่างได้ตามปกติ","ใช้สายไฟน้อยกว่า","กระแสไฟฟ้าไหลน้อยลง","แรงดันไฟฟ้าลดลง"]', 0, 'วงจรขนานมีทางเดินกระแสแยกกัน หลอดหนึ่งดับ หลอดอื่นไม่ดับตาม', 'วิเคราะห์หลักวิทยาศาสตร์และการทดลอง', 'จำคอนเซ็ปต์และตัวแปรควบคุม', '["ไฟฟ้า: วงจรไฟฟ้า (ข้อที่ 12)","Gifted"]');
INSERT INTO questions (id, subject, subject_name, track, difficulty, topic, question, options_json, correct_answer, explanation, trap, shortcut_trick, tags_json) VALUES ('s_013', 'science', 'วิทยาศาสตร์', 'Regular', 2, 'การทดสอบสารอาหารและอินดิเคเตอร์ (ข้อที่ 13)', 'เมื่อหยดสารละลายเบเนดิกต์ลงในอาหารแล้วต้ม เกิดตะกอนสีส้มอิฐ แสดงว่ามีสารใด (ข้อสอบชุดมาตรฐานที่ 13)', '["น้ำตาลโมเลกุลเดี่ยว (เช่น กลูโคส)","แป้งและคาร์โบไฮเดรตเชิงซ้อน","โปรตีน","ไขมัน"]', 0, 'เบเนดิกต์ + ความร้อน ทำปฏิกิริยากับน้ำตาลรีดิวซ์เกิดตะกอนสีส้มอิฐ', 'วิเคราะห์หลักวิทยาศาสตร์และการทดลอง', 'จำคอนเซ็ปต์และตัวแปรควบคุม', '["การทดสอบสารอาหารและอินดิเคเตอร์ (ข้อที่ 13)","Regular"]');
INSERT INTO questions (id, subject, subject_name, track, difficulty, topic, question, options_json, correct_answer, explanation, trap, shortcut_trick, tags_json) VALUES ('s_014', 'science', 'วิทยาศาสตร์', 'Gifted', 3, 'ชีววิทยาของพืช: ท่อลำเลียง (ข้อที่ 14)', 'ท่อลำเลียง โฟลเอ็ม (Phloem) ในพืชทำหน้าที่และมีทิศทางอย่างไร (ข้อสอบชุดมาตรฐานที่ 14)', '["ลำเลียงอาหารจากใบไปทั่วทุกส่วนได้ทุกทิศทาง","ลำเลียงน้ำจากรากขึ้นบนเท่านั้น","ลำเลียงแก๊สออกซิเจน","ลำเลียงแร่ธาตุลงล่างอย่างเดียว"]', 0, 'ไซเลมลำเลียงน้ำขึ้นบน ส่วนโฟลเอ็มลำเลียงอาหารได้ทุกทิศทาง', 'วิเคราะห์หลักวิทยาศาสตร์และการทดลอง', 'จำคอนเซ็ปต์และตัวแปรควบคุม', '["ชีววิทยาของพืช: ท่อลำเลียง (ข้อที่ 14)","Gifted"]');
INSERT INTO questions (id, subject, subject_name, track, difficulty, topic, question, options_json, correct_answer, explanation, trap, shortcut_trick, tags_json) VALUES ('s_015', 'science', 'วิทยาศาสตร์', 'Regular', 1, 'พันธุศาสตร์และหมู่เลือด ABO (ข้อที่ 15)', 'พ่อเลือดหมู่ A (IA i) แม่เลือดหมู่ B (IB i) ลูกมีโอกาสเลือดหมู่ใดบ้าง (ข้อสอบชุดมาตรฐานที่ 15)', '["มีโอกาสเป็นได้ทั้ง 4 หมู่ (A, B, AB, O)","หมู่ AB เท่านั้น","หมู่ A และ B เท่านั้น","ไม่มีโอกาสเป็นหมู่ O"]', 0, 'การจับคู่ยีน IA, IB, i ทำให้เกิดจีโนไทป์ IAIB, IAi, IBi, ii ครบทั้ง 4 หมู่', 'วิเคราะห์หลักวิทยาศาสตร์และการทดลอง', 'จำคอนเซ็ปต์และตัวแปรควบคุม', '["พันธุศาสตร์และหมู่เลือด ABO (ข้อที่ 15)","Regular"]');
INSERT INTO questions (id, subject, subject_name, track, difficulty, topic, question, options_json, correct_answer, explanation, trap, shortcut_trick, tags_json) VALUES ('s_016', 'science', 'วิทยาศาสตร์', 'Gifted', 2, 'ฟิสิกส์: เครื่องกลอย่างง่าย (รอกเดี่ยว) (ข้อที่ 16)', 'การใช้ รอกเดี่ยวเคลื่อนที่ ยกวัตถุหนัก 600 นิวตัน จะต้องออกแรงดึงกี่นิวตัน (ข้อสอบชุดมาตรฐานที่ 16)', '["300 นิวตัน (ผ่อนแรงได้ครึ่งหนึ่ง)","600 นิวตัน (ไม่ผ่อนแรง)","150 นิวตัน","1,200 นิวตัน"]', 0, 'รอกเดี่ยวเคลื่อนที่ช่วยผ่อนแรง 2 เท่า: F = W/2 = 600/2 = 300 N', 'วิเคราะห์หลักวิทยาศาสตร์และการทดลอง', 'จำคอนเซ็ปต์และตัวแปรควบคุม', '["ฟิสิกส์: เครื่องกลอย่างง่าย (รอกเดี่ยว) (ข้อที่ 16)","Gifted"]');
INSERT INTO questions (id, subject, subject_name, track, difficulty, topic, question, options_json, correct_answer, explanation, trap, shortcut_trick, tags_json) VALUES ('s_017', 'science', 'วิทยาศาสตร์', 'Regular', 3, 'ดาราศาสตร์: เฟสดวงจันทร์ (ข้อที่ 17)', 'ในวัน แรม 8 ค่ำ ดวงจันทร์จะปรากฏสว่างด้านใดและขึ้นเวลาใด (ข้อสอบชุดมาตรฐานที่ 17)', '["สว่างครึ่งดวงด้านซ้าย (ทิศตะวันออก) และขึ้นเวลาเที่ยงคืน","สว่างครึ่งดวงด้านขวา และขึ้นเวลาเที่ยงวัน","สว่างเต็มดวง","มืดสนิททั้งดวง"]', 0, 'ข้างแรมดวงจันทร์หันด้านสว่างไปทางซ้าย (ทิศตะวันออก) และขึ้นเวลา 24:00 น.', 'วิเคราะห์หลักวิทยาศาสตร์และการทดลอง', 'จำคอนเซ็ปต์และตัวแปรควบคุม', '["ดาราศาสตร์: เฟสดวงจันทร์ (ข้อที่ 17)","Regular"]');
INSERT INTO questions (id, subject, subject_name, track, difficulty, topic, question, options_json, correct_answer, explanation, trap, shortcut_trick, tags_json) VALUES ('s_018', 'science', 'วิทยาศาสตร์', 'Gifted', 1, 'เคมี: การทดสอบกรด-เบส (ข้อที่ 18)', 'สารละลายที่เปลี่ยนสีกระดาษลิตมัสจากแดงเป็นน้ำเงิน และฟีนอล์ฟทาลีนเป็นสีชมพู คือสารใด (ข้อสอบชุดมาตรฐานที่ 18)', '["สารละลายเบส (เช่น น้ำขี้เถ้า น้ำสบู่)","สารละลายกรด (เช่น น้ำมะนาว)","สารละลายเกลือบริสุทธิ์ (กลาง)","น้ำกลั่น"]', 0, 'เบสเปลี่ยนลิตมัสแดงเป็นน้ำเงิน และทำให้ฟีนอล์ฟทาลีนเปลี่ยนเป็นสีชมพู', 'วิเคราะห์หลักวิทยาศาสตร์และการทดลอง', 'จำคอนเซ็ปต์และตัวแปรควบคุม', '["เคมี: การทดสอบกรด-เบส (ข้อที่ 18)","Gifted"]');
INSERT INTO questions (id, subject, subject_name, track, difficulty, topic, question, options_json, correct_answer, explanation, trap, shortcut_trick, tags_json) VALUES ('s_019', 'science', 'วิทยาศาสตร์', 'Regular', 2, 'ธรณีวิทยา: วัฏจักรของหิน (ข้อที่ 19)', 'หินแกรนิตเมื่อถูกความร้อนและความดันสูงใต้โลกจะแปรสภาพเป็นหินชนิดใด (ข้อสอบชุดมาตรฐานที่ 19)', '["หินไนส์ (Gneiss)","หินอ่อน","หินชนวน","หินควอร์ตไซต์"]', 0, 'หินแกรนิต (อัคนี) แปรเป็นหินไนส์ ส่วนหินปูนแปรเป็นหินอ่อน', 'วิเคราะห์หลักวิทยาศาสตร์และการทดลอง', 'จำคอนเซ็ปต์และตัวแปรควบคุม', '["ธรณีวิทยา: วัฏจักรของหิน (ข้อที่ 19)","Regular"]');
