INSERT INTO questions (id, subject, subject_name, track, difficulty, topic, question, options_json, correct_answer, explanation, trap, shortcut_trick, tags_json) VALUES ('s_106', 'science', 'วิทยาศาสตร์', 'Gifted', 2, 'ฟิสิกส์: กระจกและเลนส์ (ข้อที่ 106)', 'กระจกที่ติดตามทางโค้งเพื่อช่วยให้มองเห็นมุมมองได้กว้างขึ้นคือกระจกชนิดใด (ข้อสอบชุดมาตรฐานที่ 106)', '["กระจกนูน (Convex Mirror)","กระจกเว้า (Concave Mirror)","กระจกเงาราบ","เลนส์เว้า"]', 0, 'กระจกนูนให้ภาพเสมือนหัวตั้งขนาดเล็กกว่าวัตถุ ช่วยขยายลานสายตาให้กว้างขึ้น', 'วิเคราะห์หลักวิทยาศาสตร์และการทดลอง', 'จำคอนเซ็ปต์และตัวแปรควบคุม', '["ฟิสิกส์: กระจกและเลนส์ (ข้อที่ 106)","Gifted"]');
INSERT INTO questions (id, subject, subject_name, track, difficulty, topic, question, options_json, correct_answer, explanation, trap, shortcut_trick, tags_json) VALUES ('s_107', 'science', 'วิทยาศาสตร์', 'Regular', 3, 'ระบบร่างกาย: การย่อยอาหาร (ข้อที่ 107)', 'อวัยวะใดทำหน้าที่ดูดซึมสารอาหารส่วนใหญ่เข้าสู่กระแสเลือด (ข้อสอบชุดมาตรฐานที่ 107)', '["ลำไส้เล็ก (Small Intestine)","กระเพาะอาหาร","ลำไส้ใหญ่","หลอดอาหาร"]', 0, 'ลำไส้เล็กมีวิลไล (Villi) ช่วยเพิ่มพื้นที่ผิวในการดูดซึมสารอาหารเกือบทั้งหมด', 'วิเคราะห์หลักวิทยาศาสตร์และการทดลอง', 'จำคอนเซ็ปต์และตัวแปรควบคุม', '["ระบบร่างกาย: การย่อยอาหาร (ข้อที่ 107)","Regular"]');
INSERT INTO questions (id, subject, subject_name, track, difficulty, topic, question, options_json, correct_answer, explanation, trap, shortcut_trick, tags_json) VALUES ('s_108', 'science', 'วิทยาศาสตร์', 'Gifted', 1, 'ไฟฟ้า: วงจรไฟฟ้า (ข้อที่ 108)', 'การต่อหลอดไฟฟ้าแบบขนานในบ้านมีข้อดีอย่างไรเมื่อเทียบกับแบบอนุกรม (ข้อสอบชุดมาตรฐานที่ 108)', '["ถ้าหลอดหนึ่งขาด หลอดอื่นยังคงสว่างได้ตามปกติ","ใช้สายไฟน้อยกว่า","กระแสไฟฟ้าไหลน้อยลง","แรงดันไฟฟ้าลดลง"]', 0, 'วงจรขนานมีทางเดินกระแสแยกกัน หลอดหนึ่งดับ หลอดอื่นไม่ดับตาม', 'วิเคราะห์หลักวิทยาศาสตร์และการทดลอง', 'จำคอนเซ็ปต์และตัวแปรควบคุม', '["ไฟฟ้า: วงจรไฟฟ้า (ข้อที่ 108)","Gifted"]');
INSERT INTO questions (id, subject, subject_name, track, difficulty, topic, question, options_json, correct_answer, explanation, trap, shortcut_trick, tags_json) VALUES ('s_109', 'science', 'วิทยาศาสตร์', 'Regular', 2, 'การทดสอบสารอาหารและอินดิเคเตอร์ (ข้อที่ 109)', 'เมื่อหยดสารละลายเบเนดิกต์ลงในอาหารแล้วต้ม เกิดตะกอนสีส้มอิฐ แสดงว่ามีสารใด (ข้อสอบชุดมาตรฐานที่ 109)', '["น้ำตาลโมเลกุลเดี่ยว (เช่น กลูโคส)","แป้งและคาร์โบไฮเดรตเชิงซ้อน","โปรตีน","ไขมัน"]', 0, 'เบเนดิกต์ + ความร้อน ทำปฏิกิริยากับน้ำตาลรีดิวซ์เกิดตะกอนสีส้มอิฐ', 'วิเคราะห์หลักวิทยาศาสตร์และการทดลอง', 'จำคอนเซ็ปต์และตัวแปรควบคุม', '["การทดสอบสารอาหารและอินดิเคเตอร์ (ข้อที่ 109)","Regular"]');
INSERT INTO questions (id, subject, subject_name, track, difficulty, topic, question, options_json, correct_answer, explanation, trap, shortcut_trick, tags_json) VALUES ('s_110', 'science', 'วิทยาศาสตร์', 'Gifted', 3, 'ชีววิทยาของพืช: ท่อลำเลียง (ข้อที่ 110)', 'ท่อลำเลียง โฟลเอ็ม (Phloem) ในพืชทำหน้าที่และมีทิศทางอย่างไร (ข้อสอบชุดมาตรฐานที่ 110)', '["ลำเลียงอาหารจากใบไปทั่วทุกส่วนได้ทุกทิศทาง","ลำเลียงน้ำจากรากขึ้นบนเท่านั้น","ลำเลียงแก๊สออกซิเจน","ลำเลียงแร่ธาตุลงล่างอย่างเดียว"]', 0, 'ไซเลมลำเลียงน้ำขึ้นบน ส่วนโฟลเอ็มลำเลียงอาหารได้ทุกทิศทาง', 'วิเคราะห์หลักวิทยาศาสตร์และการทดลอง', 'จำคอนเซ็ปต์และตัวแปรควบคุม', '["ชีววิทยาของพืช: ท่อลำเลียง (ข้อที่ 110)","Gifted"]');
INSERT INTO questions (id, subject, subject_name, track, difficulty, topic, question, options_json, correct_answer, explanation, trap, shortcut_trick, tags_json) VALUES ('s_111', 'science', 'วิทยาศาสตร์', 'Regular', 1, 'พันธุศาสตร์และหมู่เลือด ABO (ข้อที่ 111)', 'พ่อเลือดหมู่ A (IA i) แม่เลือดหมู่ B (IB i) ลูกมีโอกาสเลือดหมู่ใดบ้าง (ข้อสอบชุดมาตรฐานที่ 111)', '["มีโอกาสเป็นได้ทั้ง 4 หมู่ (A, B, AB, O)","หมู่ AB เท่านั้น","หมู่ A และ B เท่านั้น","ไม่มีโอกาสเป็นหมู่ O"]', 0, 'การจับคู่ยีน IA, IB, i ทำให้เกิดจีโนไทป์ IAIB, IAi, IBi, ii ครบทั้ง 4 หมู่', 'วิเคราะห์หลักวิทยาศาสตร์และการทดลอง', 'จำคอนเซ็ปต์และตัวแปรควบคุม', '["พันธุศาสตร์และหมู่เลือด ABO (ข้อที่ 111)","Regular"]');
INSERT INTO questions (id, subject, subject_name, track, difficulty, topic, question, options_json, correct_answer, explanation, trap, shortcut_trick, tags_json) VALUES ('s_112', 'science', 'วิทยาศาสตร์', 'Gifted', 2, 'ฟิสิกส์: เครื่องกลอย่างง่าย (รอกเดี่ยว) (ข้อที่ 112)', 'การใช้ รอกเดี่ยวเคลื่อนที่ ยกวัตถุหนัก 600 นิวตัน จะต้องออกแรงดึงกี่นิวตัน (ข้อสอบชุดมาตรฐานที่ 112)', '["300 นิวตัน (ผ่อนแรงได้ครึ่งหนึ่ง)","600 นิวตัน (ไม่ผ่อนแรง)","150 นิวตัน","1,200 นิวตัน"]', 0, 'รอกเดี่ยวเคลื่อนที่ช่วยผ่อนแรง 2 เท่า: F = W/2 = 600/2 = 300 N', 'วิเคราะห์หลักวิทยาศาสตร์และการทดลอง', 'จำคอนเซ็ปต์และตัวแปรควบคุม', '["ฟิสิกส์: เครื่องกลอย่างง่าย (รอกเดี่ยว) (ข้อที่ 112)","Gifted"]');
INSERT INTO questions (id, subject, subject_name, track, difficulty, topic, question, options_json, correct_answer, explanation, trap, shortcut_trick, tags_json) VALUES ('s_113', 'science', 'วิทยาศาสตร์', 'Regular', 3, 'ดาราศาสตร์: เฟสดวงจันทร์ (ข้อที่ 113)', 'ในวัน แรม 8 ค่ำ ดวงจันทร์จะปรากฏสว่างด้านใดและขึ้นเวลาใด (ข้อสอบชุดมาตรฐานที่ 113)', '["สว่างครึ่งดวงด้านซ้าย (ทิศตะวันออก) และขึ้นเวลาเที่ยงคืน","สว่างครึ่งดวงด้านขวา และขึ้นเวลาเที่ยงวัน","สว่างเต็มดวง","มืดสนิททั้งดวง"]', 0, 'ข้างแรมดวงจันทร์หันด้านสว่างไปทางซ้าย (ทิศตะวันออก) และขึ้นเวลา 24:00 น.', 'วิเคราะห์หลักวิทยาศาสตร์และการทดลอง', 'จำคอนเซ็ปต์และตัวแปรควบคุม', '["ดาราศาสตร์: เฟสดวงจันทร์ (ข้อที่ 113)","Regular"]');
INSERT INTO questions (id, subject, subject_name, track, difficulty, topic, question, options_json, correct_answer, explanation, trap, shortcut_trick, tags_json) VALUES ('s_114', 'science', 'วิทยาศาสตร์', 'Gifted', 1, 'เคมี: การทดสอบกรด-เบส (ข้อที่ 114)', 'สารละลายที่เปลี่ยนสีกระดาษลิตมัสจากแดงเป็นน้ำเงิน และฟีนอล์ฟทาลีนเป็นสีชมพู คือสารใด (ข้อสอบชุดมาตรฐานที่ 114)', '["สารละลายเบส (เช่น น้ำขี้เถ้า น้ำสบู่)","สารละลายกรด (เช่น น้ำมะนาว)","สารละลายเกลือบริสุทธิ์ (กลาง)","น้ำกลั่น"]', 0, 'เบสเปลี่ยนลิตมัสแดงเป็นน้ำเงิน และทำให้ฟีนอล์ฟทาลีนเปลี่ยนเป็นสีชมพู', 'วิเคราะห์หลักวิทยาศาสตร์และการทดลอง', 'จำคอนเซ็ปต์และตัวแปรควบคุม', '["เคมี: การทดสอบกรด-เบส (ข้อที่ 114)","Gifted"]');
INSERT INTO questions (id, subject, subject_name, track, difficulty, topic, question, options_json, correct_answer, explanation, trap, shortcut_trick, tags_json) VALUES ('s_115', 'science', 'วิทยาศาสตร์', 'Regular', 2, 'ธรณีวิทยา: วัฏจักรของหิน (ข้อที่ 115)', 'หินแกรนิตเมื่อถูกความร้อนและความดันสูงใต้โลกจะแปรสภาพเป็นหินชนิดใด (ข้อสอบชุดมาตรฐานที่ 115)', '["หินไนส์ (Gneiss)","หินอ่อน","หินชนวน","หินควอร์ตไซต์"]', 0, 'หินแกรนิต (อัคนี) แปรเป็นหินไนส์ ส่วนหินปูนแปรเป็นหินอ่อน', 'วิเคราะห์หลักวิทยาศาสตร์และการทดลอง', 'จำคอนเซ็ปต์และตัวแปรควบคุม', '["ธรณีวิทยา: วัฏจักรของหิน (ข้อที่ 115)","Regular"]');
INSERT INTO questions (id, subject, subject_name, track, difficulty, topic, question, options_json, correct_answer, explanation, trap, shortcut_trick, tags_json) VALUES ('s_116', 'science', 'วิทยาศาสตร์', 'Gifted', 3, 'ฟิสิกส์: การถ่ายโอนความร้อน (ข้อที่ 116)', 'ความร้อนจากดวงอาทิตย์เดินทางผ่านสุญญากาศในอวกาศมายังโลกโดยวิธีใด (ข้อสอบชุดมาตรฐานที่ 116)', '["การแผ่รังสีความร้อน (Radiation)","การพาความร้อน (Convection)","การนำความร้อน (Conduction)","การพาและการนำ"]', 0, 'การแผ่รังสีความร้อนไม่ต้องอาศัยตัวกลาง สามารถเดินทางผ่านสุญญากาศได้', 'วิเคราะห์หลักวิทยาศาสตร์และการทดลอง', 'จำคอนเซ็ปต์และตัวแปรควบคุม', '["ฟิสิกส์: การถ่ายโอนความร้อน (ข้อที่ 116)","Gifted"]');
INSERT INTO questions (id, subject, subject_name, track, difficulty, topic, question, options_json, correct_answer, explanation, trap, shortcut_trick, tags_json) VALUES ('s_117', 'science', 'วิทยาศาสตร์', 'Regular', 1, 'นิเวศวิทยา: ภาวะความสัมพันธ์ (ข้อที่ 117)', 'ความสัมพันธ์ระหว่าง ผึ้งกับดอกไม้ จัดเป็นภาวะความสัมพันธ์แบบใด (ข้อสอบชุดมาตรฐานที่ 117)', '["ภาวะได้ประโยชน์ร่วมกัน (+/+)","ภาวะพึ่งพากัน","ภาวะอิงอาศัย (+/0)","ภาวะปรสิต (+/-)"]', 0, 'ผึ้งได้น้ำหวาน ดอกไม้ได้ผสมเกสร แยกกันอยู่ได้ เป็นภาวะได้ประโยชน์ร่วมกัน', 'วิเคราะห์หลักวิทยาศาสตร์และการทดลอง', 'จำคอนเซ็ปต์และตัวแปรควบคุม', '["นิเวศวิทยา: ภาวะความสัมพันธ์ (ข้อที่ 117)","Regular"]');
