INSERT INTO questions (id, subject, subject_name, track, difficulty, topic, question, options_json, correct_answer, explanation, trap, shortcut_trick, tags_json) VALUES ('s_192', 'science', 'วิทยาศาสตร์', 'Gifted', 1, 'ไฟฟ้า: วงจรไฟฟ้า (ข้อที่ 192)', 'การต่อหลอดไฟฟ้าแบบขนานในบ้านมีข้อดีอย่างไรเมื่อเทียบกับแบบอนุกรม (ข้อสอบชุดมาตรฐานที่ 192)', '["ถ้าหลอดหนึ่งขาด หลอดอื่นยังคงสว่างได้ตามปกติ","ใช้สายไฟน้อยกว่า","กระแสไฟฟ้าไหลน้อยลง","แรงดันไฟฟ้าลดลง"]', 0, 'วงจรขนานมีทางเดินกระแสแยกกัน หลอดหนึ่งดับ หลอดอื่นไม่ดับตาม', 'วิเคราะห์หลักวิทยาศาสตร์และการทดลอง', 'จำคอนเซ็ปต์และตัวแปรควบคุม', '["ไฟฟ้า: วงจรไฟฟ้า (ข้อที่ 192)","Gifted"]');
INSERT INTO questions (id, subject, subject_name, track, difficulty, topic, question, options_json, correct_answer, explanation, trap, shortcut_trick, tags_json) VALUES ('s_193', 'science', 'วิทยาศาสตร์', 'Regular', 2, 'การทดสอบสารอาหารและอินดิเคเตอร์ (ข้อที่ 193)', 'เมื่อหยดสารละลายเบเนดิกต์ลงในอาหารแล้วต้ม เกิดตะกอนสีส้มอิฐ แสดงว่ามีสารใด (ข้อสอบชุดมาตรฐานที่ 193)', '["น้ำตาลโมเลกุลเดี่ยว (เช่น กลูโคส)","แป้งและคาร์โบไฮเดรตเชิงซ้อน","โปรตีน","ไขมัน"]', 0, 'เบเนดิกต์ + ความร้อน ทำปฏิกิริยากับน้ำตาลรีดิวซ์เกิดตะกอนสีส้มอิฐ', 'วิเคราะห์หลักวิทยาศาสตร์และการทดลอง', 'จำคอนเซ็ปต์และตัวแปรควบคุม', '["การทดสอบสารอาหารและอินดิเคเตอร์ (ข้อที่ 193)","Regular"]');
INSERT INTO questions (id, subject, subject_name, track, difficulty, topic, question, options_json, correct_answer, explanation, trap, shortcut_trick, tags_json) VALUES ('s_194', 'science', 'วิทยาศาสตร์', 'Gifted', 3, 'ชีววิทยาของพืช: ท่อลำเลียง (ข้อที่ 194)', 'ท่อลำเลียง โฟลเอ็ม (Phloem) ในพืชทำหน้าที่และมีทิศทางอย่างไร (ข้อสอบชุดมาตรฐานที่ 194)', '["ลำเลียงอาหารจากใบไปทั่วทุกส่วนได้ทุกทิศทาง","ลำเลียงน้ำจากรากขึ้นบนเท่านั้น","ลำเลียงแก๊สออกซิเจน","ลำเลียงแร่ธาตุลงล่างอย่างเดียว"]', 0, 'ไซเลมลำเลียงน้ำขึ้นบน ส่วนโฟลเอ็มลำเลียงอาหารได้ทุกทิศทาง', 'วิเคราะห์หลักวิทยาศาสตร์และการทดลอง', 'จำคอนเซ็ปต์และตัวแปรควบคุม', '["ชีววิทยาของพืช: ท่อลำเลียง (ข้อที่ 194)","Gifted"]');
INSERT INTO questions (id, subject, subject_name, track, difficulty, topic, question, options_json, correct_answer, explanation, trap, shortcut_trick, tags_json) VALUES ('s_195', 'science', 'วิทยาศาสตร์', 'Regular', 1, 'พันธุศาสตร์และหมู่เลือด ABO (ข้อที่ 195)', 'พ่อเลือดหมู่ A (IA i) แม่เลือดหมู่ B (IB i) ลูกมีโอกาสเลือดหมู่ใดบ้าง (ข้อสอบชุดมาตรฐานที่ 195)', '["มีโอกาสเป็นได้ทั้ง 4 หมู่ (A, B, AB, O)","หมู่ AB เท่านั้น","หมู่ A และ B เท่านั้น","ไม่มีโอกาสเป็นหมู่ O"]', 0, 'การจับคู่ยีน IA, IB, i ทำให้เกิดจีโนไทป์ IAIB, IAi, IBi, ii ครบทั้ง 4 หมู่', 'วิเคราะห์หลักวิทยาศาสตร์และการทดลอง', 'จำคอนเซ็ปต์และตัวแปรควบคุม', '["พันธุศาสตร์และหมู่เลือด ABO (ข้อที่ 195)","Regular"]');
INSERT INTO questions (id, subject, subject_name, track, difficulty, topic, question, options_json, correct_answer, explanation, trap, shortcut_trick, tags_json) VALUES ('s_196', 'science', 'วิทยาศาสตร์', 'Gifted', 2, 'ฟิสิกส์: เครื่องกลอย่างง่าย (รอกเดี่ยว) (ข้อที่ 196)', 'การใช้ รอกเดี่ยวเคลื่อนที่ ยกวัตถุหนัก 600 นิวตัน จะต้องออกแรงดึงกี่นิวตัน (ข้อสอบชุดมาตรฐานที่ 196)', '["300 นิวตัน (ผ่อนแรงได้ครึ่งหนึ่ง)","600 นิวตัน (ไม่ผ่อนแรง)","150 นิวตัน","1,200 นิวตัน"]', 0, 'รอกเดี่ยวเคลื่อนที่ช่วยผ่อนแรง 2 เท่า: F = W/2 = 600/2 = 300 N', 'วิเคราะห์หลักวิทยาศาสตร์และการทดลอง', 'จำคอนเซ็ปต์และตัวแปรควบคุม', '["ฟิสิกส์: เครื่องกลอย่างง่าย (รอกเดี่ยว) (ข้อที่ 196)","Gifted"]');
INSERT INTO questions (id, subject, subject_name, track, difficulty, topic, question, options_json, correct_answer, explanation, trap, shortcut_trick, tags_json) VALUES ('s_197', 'science', 'วิทยาศาสตร์', 'Regular', 3, 'ดาราศาสตร์: เฟสดวงจันทร์ (ข้อที่ 197)', 'ในวัน แรม 8 ค่ำ ดวงจันทร์จะปรากฏสว่างด้านใดและขึ้นเวลาใด (ข้อสอบชุดมาตรฐานที่ 197)', '["สว่างครึ่งดวงด้านซ้าย (ทิศตะวันออก) และขึ้นเวลาเที่ยงคืน","สว่างครึ่งดวงด้านขวา และขึ้นเวลาเที่ยงวัน","สว่างเต็มดวง","มืดสนิททั้งดวง"]', 0, 'ข้างแรมดวงจันทร์หันด้านสว่างไปทางซ้าย (ทิศตะวันออก) และขึ้นเวลา 24:00 น.', 'วิเคราะห์หลักวิทยาศาสตร์และการทดลอง', 'จำคอนเซ็ปต์และตัวแปรควบคุม', '["ดาราศาสตร์: เฟสดวงจันทร์ (ข้อที่ 197)","Regular"]');
INSERT INTO questions (id, subject, subject_name, track, difficulty, topic, question, options_json, correct_answer, explanation, trap, shortcut_trick, tags_json) VALUES ('s_198', 'science', 'วิทยาศาสตร์', 'Gifted', 1, 'เคมี: การทดสอบกรด-เบส (ข้อที่ 198)', 'สารละลายที่เปลี่ยนสีกระดาษลิตมัสจากแดงเป็นน้ำเงิน และฟีนอล์ฟทาลีนเป็นสีชมพู คือสารใด (ข้อสอบชุดมาตรฐานที่ 198)', '["สารละลายเบส (เช่น น้ำขี้เถ้า น้ำสบู่)","สารละลายกรด (เช่น น้ำมะนาว)","สารละลายเกลือบริสุทธิ์ (กลาง)","น้ำกลั่น"]', 0, 'เบสเปลี่ยนลิตมัสแดงเป็นน้ำเงิน และทำให้ฟีนอล์ฟทาลีนเปลี่ยนเป็นสีชมพู', 'วิเคราะห์หลักวิทยาศาสตร์และการทดลอง', 'จำคอนเซ็ปต์และตัวแปรควบคุม', '["เคมี: การทดสอบกรด-เบส (ข้อที่ 198)","Gifted"]');
INSERT INTO questions (id, subject, subject_name, track, difficulty, topic, question, options_json, correct_answer, explanation, trap, shortcut_trick, tags_json) VALUES ('s_199', 'science', 'วิทยาศาสตร์', 'Regular', 2, 'ธรณีวิทยา: วัฏจักรของหิน (ข้อที่ 199)', 'หินแกรนิตเมื่อถูกความร้อนและความดันสูงใต้โลกจะแปรสภาพเป็นหินชนิดใด (ข้อสอบชุดมาตรฐานที่ 199)', '["หินไนส์ (Gneiss)","หินอ่อน","หินชนวน","หินควอร์ตไซต์"]', 0, 'หินแกรนิต (อัคนี) แปรเป็นหินไนส์ ส่วนหินปูนแปรเป็นหินอ่อน', 'วิเคราะห์หลักวิทยาศาสตร์และการทดลอง', 'จำคอนเซ็ปต์และตัวแปรควบคุม', '["ธรณีวิทยา: วัฏจักรของหิน (ข้อที่ 199)","Regular"]');
INSERT INTO questions (id, subject, subject_name, track, difficulty, topic, question, options_json, correct_answer, explanation, trap, shortcut_trick, tags_json) VALUES ('s_200', 'science', 'วิทยาศาสตร์', 'Gifted', 3, 'ฟิสิกส์: การถ่ายโอนความร้อน (ข้อที่ 200)', 'ความร้อนจากดวงอาทิตย์เดินทางผ่านสุญญากาศในอวกาศมายังโลกโดยวิธีใด (ข้อสอบชุดมาตรฐานที่ 200)', '["การแผ่รังสีความร้อน (Radiation)","การพาความร้อน (Convection)","การนำความร้อน (Conduction)","การพาและการนำ"]', 0, 'การแผ่รังสีความร้อนไม่ต้องอาศัยตัวกลาง สามารถเดินทางผ่านสุญญากาศได้', 'วิเคราะห์หลักวิทยาศาสตร์และการทดลอง', 'จำคอนเซ็ปต์และตัวแปรควบคุม', '["ฟิสิกส์: การถ่ายโอนความร้อน (ข้อที่ 200)","Gifted"]');
INSERT INTO questions (id, subject, subject_name, track, difficulty, topic, question, options_json, correct_answer, explanation, trap, shortcut_trick, tags_json) VALUES ('e_001', 'english', 'ภาษาอังกฤษ', 'Regular', 2, 'Subjunctive / Wish (Item 1)', 'I wish I ______ enough time to join the school camping trip tomorrow. (Standard Test #1)', '["had","have","will have","have had"]', 0, 'Wish ในปัจจุบันใช้โครงสร้าง Past Simple (V.2) เพื่อแสดงความปรารถนา', 'Check tense, subject-verb agreement, and context', 'Look for grammar trigger keywords', '["Subjunctive / Wish (Item 1)","Regular"]');
INSERT INTO questions (id, subject, subject_name, track, difficulty, topic, question, options_json, correct_answer, explanation, trap, shortcut_trick, tags_json) VALUES ('e_002', 'english', 'ภาษาอังกฤษ', 'Gifted', 3, 'Phrasal Verbs (Item 2)', 'Could you please ______ the light before you leave the bedroom? (Standard Test #2)', '["turn off","turn on","turn into","turn over"]', 0, 'turn off แปลว่า ปิด (ไฟ/เครื่องใช้ไฟฟ้า)', 'Check tense, subject-verb agreement, and context', 'Look for grammar trigger keywords', '["Phrasal Verbs (Item 2)","Gifted"]');
INSERT INTO questions (id, subject, subject_name, track, difficulty, topic, question, options_json, correct_answer, explanation, trap, shortcut_trick, tags_json) VALUES ('e_003', 'english', 'ภาษาอังกฤษ', 'Regular', 1, 'Gerund vs Infinitive (Item 3)', 'My brother enjoys ______ basketball with his friends after school. (Standard Test #3)', '["playing","to play","play","played"]', 0, 'กริยา enjoy ตามด้วย Gerund (V-ing) เสมอ', 'Check tense, subject-verb agreement, and context', 'Look for grammar trigger keywords', '["Gerund vs Infinitive (Item 3)","Regular"]');
INSERT INTO questions (id, subject, subject_name, track, difficulty, topic, question, options_json, correct_answer, explanation, trap, shortcut_trick, tags_json) VALUES ('e_004', 'english', 'ภาษาอังกฤษ', 'Gifted', 2, 'Quantifiers (Item 4)', 'There are very ______ students in the library today because of the holiday. (Standard Test #4)', '["few","little","much","a little"]', 0, 'students เป็นนามนับได้พหูพจน์ ใช้ few แปลว่ามีน้อยมาก', 'Check tense, subject-verb agreement, and context', 'Look for grammar trigger keywords', '["Quantifiers (Item 4)","Gifted"]');
INSERT INTO questions (id, subject, subject_name, track, difficulty, topic, question, options_json, correct_answer, explanation, trap, shortcut_trick, tags_json) VALUES ('e_005', 'english', 'ภาษาอังกฤษ', 'Regular', 3, 'Prepositions (Item 5)', 'Are you interested ______ joining our English conversation club? (Standard Test #5)', '["in","at","for","with"]', 0, 'interested คู่กับบุพบท in เสมอ (interested in = สนใจใน)', 'Check tense, subject-verb agreement, and context', 'Look for grammar trigger keywords', '["Prepositions (Item 5)","Regular"]');
INSERT INTO questions (id, subject, subject_name, track, difficulty, topic, question, options_json, correct_answer, explanation, trap, shortcut_trick, tags_json) VALUES ('e_006', 'english', 'ภาษาอังกฤษ', 'Gifted', 1, 'Idioms (Item 6)', 'Passing the final exam was a ______ for him because he studied very hard. (Standard Test #6)', '["piece of cake","cup of tea","cold feet","spill the beans"]', 0, 'a piece of cake เป็นสำนวนแปลว่า ง่ายมากๆ', 'Check tense, subject-verb agreement, and context', 'Look for grammar trigger keywords', '["Idioms (Item 6)","Gifted"]');
INSERT INTO questions (id, subject, subject_name, track, difficulty, topic, question, options_json, correct_answer, explanation, trap, shortcut_trick, tags_json) VALUES ('e_007', 'english', 'ภาษาอังกฤษ', 'Regular', 2, 'Conjunctions (Item 7)', '______ it was raining heavily, we enjoyed our picnic in the park. (Standard Test #7)', '["Although","Because","Therefore","Despite of"]', 0, 'Although (แม้ว่า) ใช้เชื่อมประโยคที่แสดงความขัดแย้ง', 'Check tense, subject-verb agreement, and context', 'Look for grammar trigger keywords', '["Conjunctions (Item 7)","Regular"]');
INSERT INTO questions (id, subject, subject_name, track, difficulty, topic, question, options_json, correct_answer, explanation, trap, shortcut_trick, tags_json) VALUES ('e_008', 'english', 'ภาษาอังกฤษ', 'Gifted', 3, 'Reported Speech (Item 8)', 'She said, "I like chocolate." -> She said that she ______ chocolate. (Standard Test #8)', '["liked","likes","is liking","has liked"]', 0, 'เปลี่ยน Present Simple (like) เป็น Past Simple (liked)', 'Check tense, subject-verb agreement, and context', 'Look for grammar trigger keywords', '["Reported Speech (Item 8)","Gifted"]');
INSERT INTO questions (id, subject, subject_name, track, difficulty, topic, question, options_json, correct_answer, explanation, trap, shortcut_trick, tags_json) VALUES ('e_009', 'english', 'ภาษาอังกฤษ', 'Regular', 1, 'Conditionals (Item 9)', 'If it rains tomorrow, we ______ the outdoor football match. (Standard Test #9)', '["will cancel","cancelled","would cancel","cancel"]', 0, 'First Conditional: If + Present Simple, S + will + V.inf', 'Check tense, subject-verb agreement, and context', 'Look for grammar trigger keywords', '["Conditionals (Item 9)","Regular"]');
INSERT INTO questions (id, subject, subject_name, track, difficulty, topic, question, options_json, correct_answer, explanation, trap, shortcut_trick, tags_json) VALUES ('e_010', 'english', 'ภาษาอังกฤษ', 'Gifted', 2, 'Articles (Item 10)', 'She is ______ honest girl who always tells the truth. (Standard Test #10)', '["an","a","the","no article"]', 0, 'honest ออกเสียงสระ อ- จึงต้องใช้คำนำหน้าว่า an', 'Check tense, subject-verb agreement, and context', 'Look for grammar trigger keywords', '["Articles (Item 10)","Gifted"]');
INSERT INTO questions (id, subject, subject_name, track, difficulty, topic, question, options_json, correct_answer, explanation, trap, shortcut_trick, tags_json) VALUES ('e_011', 'english', 'ภาษาอังกฤษ', 'Regular', 3, 'Passive Voice (Item 11)', 'The famous novel ______ by a Thai author in 1995. (Standard Test #11)', '["was written","wrote","is written","was writing"]', 0, 'ประธานเป็นผู้ถูกกระทำในอดีต: S + was/were + V.3 (was written)', 'Check tense, subject-verb agreement, and context', 'Look for grammar trigger keywords', '["Passive Voice (Item 11)","Regular"]');
INSERT INTO questions (id, subject, subject_name, track, difficulty, topic, question, options_json, correct_answer, explanation, trap, shortcut_trick, tags_json) VALUES ('e_012', 'english', 'ภาษาอังกฤษ', 'Gifted', 1, 'Question Tags (Item 12)', 'You haven''t finished your homework yet, ______? (Standard Test #12)', '["have you","haven''t you","did you","do you"]', 0, 'ประโยคหน้าปฏิเสธ (haven''t finished) ท้ายต้องเป็นบอกเล่า (have you)', 'Check tense, subject-verb agreement, and context', 'Look for grammar trigger keywords', '["Question Tags (Item 12)","Gifted"]');
INSERT INTO questions (id, subject, subject_name, track, difficulty, topic, question, options_json, correct_answer, explanation, trap, shortcut_trick, tags_json) VALUES ('e_013', 'english', 'ภาษาอังกฤษ', 'Regular', 2, 'Subjunctive / Wish (Item 13)', 'I wish I ______ enough time to join the school camping trip tomorrow. (Standard Test #13)', '["had","have","will have","have had"]', 0, 'Wish ในปัจจุบันใช้โครงสร้าง Past Simple (V.2) เพื่อแสดงความปรารถนา', 'Check tense, subject-verb agreement, and context', 'Look for grammar trigger keywords', '["Subjunctive / Wish (Item 13)","Regular"]');
INSERT INTO questions (id, subject, subject_name, track, difficulty, topic, question, options_json, correct_answer, explanation, trap, shortcut_trick, tags_json) VALUES ('e_014', 'english', 'ภาษาอังกฤษ', 'Gifted', 3, 'Phrasal Verbs (Item 14)', 'Could you please ______ the light before you leave the bedroom? (Standard Test #14)', '["turn off","turn on","turn into","turn over"]', 0, 'turn off แปลว่า ปิด (ไฟ/เครื่องใช้ไฟฟ้า)', 'Check tense, subject-verb agreement, and context', 'Look for grammar trigger keywords', '["Phrasal Verbs (Item 14)","Gifted"]');
INSERT INTO questions (id, subject, subject_name, track, difficulty, topic, question, options_json, correct_answer, explanation, trap, shortcut_trick, tags_json) VALUES ('e_015', 'english', 'ภาษาอังกฤษ', 'Regular', 1, 'Gerund vs Infinitive (Item 15)', 'My brother enjoys ______ basketball with his friends after school. (Standard Test #15)', '["playing","to play","play","played"]', 0, 'กริยา enjoy ตามด้วย Gerund (V-ing) เสมอ', 'Check tense, subject-verb agreement, and context', 'Look for grammar trigger keywords', '["Gerund vs Infinitive (Item 15)","Regular"]');
INSERT INTO questions (id, subject, subject_name, track, difficulty, topic, question, options_json, correct_answer, explanation, trap, shortcut_trick, tags_json) VALUES ('e_016', 'english', 'ภาษาอังกฤษ', 'Gifted', 2, 'Quantifiers (Item 16)', 'There are very ______ students in the library today because of the holiday. (Standard Test #16)', '["few","little","much","a little"]', 0, 'students เป็นนามนับได้พหูพจน์ ใช้ few แปลว่ามีน้อยมาก', 'Check tense, subject-verb agreement, and context', 'Look for grammar trigger keywords', '["Quantifiers (Item 16)","Gifted"]');
INSERT INTO questions (id, subject, subject_name, track, difficulty, topic, question, options_json, correct_answer, explanation, trap, shortcut_trick, tags_json) VALUES ('e_017', 'english', 'ภาษาอังกฤษ', 'Regular', 3, 'Prepositions (Item 17)', 'Are you interested ______ joining our English conversation club? (Standard Test #17)', '["in","at","for","with"]', 0, 'interested คู่กับบุพบท in เสมอ (interested in = สนใจใน)', 'Check tense, subject-verb agreement, and context', 'Look for grammar trigger keywords', '["Prepositions (Item 17)","Regular"]');
INSERT INTO questions (id, subject, subject_name, track, difficulty, topic, question, options_json, correct_answer, explanation, trap, shortcut_trick, tags_json) VALUES ('e_018', 'english', 'ภาษาอังกฤษ', 'Gifted', 1, 'Idioms (Item 18)', 'Passing the final exam was a ______ for him because he studied very hard. (Standard Test #18)', '["piece of cake","cup of tea","cold feet","spill the beans"]', 0, 'a piece of cake เป็นสำนวนแปลว่า ง่ายมากๆ', 'Check tense, subject-verb agreement, and context', 'Look for grammar trigger keywords', '["Idioms (Item 18)","Gifted"]');
INSERT INTO questions (id, subject, subject_name, track, difficulty, topic, question, options_json, correct_answer, explanation, trap, shortcut_trick, tags_json) VALUES ('e_019', 'english', 'ภาษาอังกฤษ', 'Regular', 2, 'Conjunctions (Item 19)', '______ it was raining heavily, we enjoyed our picnic in the park. (Standard Test #19)', '["Although","Because","Therefore","Despite of"]', 0, 'Although (แม้ว่า) ใช้เชื่อมประโยคที่แสดงความขัดแย้ง', 'Check tense, subject-verb agreement, and context', 'Look for grammar trigger keywords', '["Conjunctions (Item 19)","Regular"]');
