INSERT INTO questions (id, subject, subject_name, track, difficulty, topic, question, options_json, correct_answer, explanation, trap, shortcut_trick, tags_json) VALUES ('e_054', 'english', 'ภาษาอังกฤษ', 'Gifted', 1, 'Idioms (Item 54)', 'Passing the final exam was a ______ for him because he studied very hard. (Standard Test #54)', '["piece of cake","cup of tea","cold feet","spill the beans"]', 0, 'a piece of cake เป็นสำนวนแปลว่า ง่ายมากๆ', 'Check tense, subject-verb agreement, and context', 'Look for grammar trigger keywords', '["Idioms (Item 54)","Gifted"]');
INSERT INTO questions (id, subject, subject_name, track, difficulty, topic, question, options_json, correct_answer, explanation, trap, shortcut_trick, tags_json) VALUES ('e_055', 'english', 'ภาษาอังกฤษ', 'Regular', 2, 'Conjunctions (Item 55)', '______ it was raining heavily, we enjoyed our picnic in the park. (Standard Test #55)', '["Although","Because","Therefore","Despite of"]', 0, 'Although (แม้ว่า) ใช้เชื่อมประโยคที่แสดงความขัดแย้ง', 'Check tense, subject-verb agreement, and context', 'Look for grammar trigger keywords', '["Conjunctions (Item 55)","Regular"]');
INSERT INTO questions (id, subject, subject_name, track, difficulty, topic, question, options_json, correct_answer, explanation, trap, shortcut_trick, tags_json) VALUES ('e_056', 'english', 'ภาษาอังกฤษ', 'Gifted', 3, 'Reported Speech (Item 56)', 'She said, "I like chocolate." -> She said that she ______ chocolate. (Standard Test #56)', '["liked","likes","is liking","has liked"]', 0, 'เปลี่ยน Present Simple (like) เป็น Past Simple (liked)', 'Check tense, subject-verb agreement, and context', 'Look for grammar trigger keywords', '["Reported Speech (Item 56)","Gifted"]');
INSERT INTO questions (id, subject, subject_name, track, difficulty, topic, question, options_json, correct_answer, explanation, trap, shortcut_trick, tags_json) VALUES ('e_057', 'english', 'ภาษาอังกฤษ', 'Regular', 1, 'Conditionals (Item 57)', 'If it rains tomorrow, we ______ the outdoor football match. (Standard Test #57)', '["will cancel","cancelled","would cancel","cancel"]', 0, 'First Conditional: If + Present Simple, S + will + V.inf', 'Check tense, subject-verb agreement, and context', 'Look for grammar trigger keywords', '["Conditionals (Item 57)","Regular"]');
INSERT INTO questions (id, subject, subject_name, track, difficulty, topic, question, options_json, correct_answer, explanation, trap, shortcut_trick, tags_json) VALUES ('e_058', 'english', 'ภาษาอังกฤษ', 'Gifted', 2, 'Articles (Item 58)', 'She is ______ honest girl who always tells the truth. (Standard Test #58)', '["an","a","the","no article"]', 0, 'honest ออกเสียงสระ อ- จึงต้องใช้คำนำหน้าว่า an', 'Check tense, subject-verb agreement, and context', 'Look for grammar trigger keywords', '["Articles (Item 58)","Gifted"]');
INSERT INTO questions (id, subject, subject_name, track, difficulty, topic, question, options_json, correct_answer, explanation, trap, shortcut_trick, tags_json) VALUES ('e_059', 'english', 'ภาษาอังกฤษ', 'Regular', 3, 'Passive Voice (Item 59)', 'The famous novel ______ by a Thai author in 1995. (Standard Test #59)', '["was written","wrote","is written","was writing"]', 0, 'ประธานเป็นผู้ถูกกระทำในอดีต: S + was/were + V.3 (was written)', 'Check tense, subject-verb agreement, and context', 'Look for grammar trigger keywords', '["Passive Voice (Item 59)","Regular"]');
