INSERT INTO questions (id, subject, subject_name, track, difficulty, topic, question, options_json, correct_answer, explanation, trap, shortcut_trick, tags_json) VALUES ('e_094', 'english', 'ภาษาอังกฤษ', 'Gifted', 2, 'Articles (Item 94)', 'She is ______ honest girl who always tells the truth. (Standard Test #94)', '["an","a","the","no article"]', 0, 'honest ออกเสียงสระ อ- จึงต้องใช้คำนำหน้าว่า an', 'Check tense, subject-verb agreement, and context', 'Look for grammar trigger keywords', '["Articles (Item 94)","Gifted"]');
INSERT INTO questions (id, subject, subject_name, track, difficulty, topic, question, options_json, correct_answer, explanation, trap, shortcut_trick, tags_json) VALUES ('e_095', 'english', 'ภาษาอังกฤษ', 'Regular', 3, 'Passive Voice (Item 95)', 'The famous novel ______ by a Thai author in 1995. (Standard Test #95)', '["was written","wrote","is written","was writing"]', 0, 'ประธานเป็นผู้ถูกกระทำในอดีต: S + was/were + V.3 (was written)', 'Check tense, subject-verb agreement, and context', 'Look for grammar trigger keywords', '["Passive Voice (Item 95)","Regular"]');
INSERT INTO questions (id, subject, subject_name, track, difficulty, topic, question, options_json, correct_answer, explanation, trap, shortcut_trick, tags_json) VALUES ('e_096', 'english', 'ภาษาอังกฤษ', 'Gifted', 1, 'Question Tags (Item 96)', 'You haven''t finished your homework yet, ______? (Standard Test #96)', '["have you","haven''t you","did you","do you"]', 0, 'ประโยคหน้าปฏิเสธ (haven''t finished) ท้ายต้องเป็นบอกเล่า (have you)', 'Check tense, subject-verb agreement, and context', 'Look for grammar trigger keywords', '["Question Tags (Item 96)","Gifted"]');
