INSERT INTO questions (id, subject, subject_name, track, difficulty, topic, question, options_json, correct_answer, explanation, trap, shortcut_trick, tags_json) VALUES ('e_134', 'english', 'ภาษาอังกฤษ', 'Gifted', 3, 'Phrasal Verbs (Item 134)', 'Could you please ______ the light before you leave the bedroom? (Standard Test #134)', '["turn off","turn on","turn into","turn over"]', 0, 'turn off แปลว่า ปิด (ไฟ/เครื่องใช้ไฟฟ้า)', 'Check tense, subject-verb agreement, and context', 'Look for grammar trigger keywords', '["Phrasal Verbs (Item 134)","Gifted"]');
INSERT INTO questions (id, subject, subject_name, track, difficulty, topic, question, options_json, correct_answer, explanation, trap, shortcut_trick, tags_json) VALUES ('e_135', 'english', 'ภาษาอังกฤษ', 'Regular', 1, 'Gerund vs Infinitive (Item 135)', 'My brother enjoys ______ basketball with his friends after school. (Standard Test #135)', '["playing","to play","play","played"]', 0, 'กริยา enjoy ตามด้วย Gerund (V-ing) เสมอ', 'Check tense, subject-verb agreement, and context', 'Look for grammar trigger keywords', '["Gerund vs Infinitive (Item 135)","Regular"]');
INSERT INTO questions (id, subject, subject_name, track, difficulty, topic, question, options_json, correct_answer, explanation, trap, shortcut_trick, tags_json) VALUES ('e_136', 'english', 'ภาษาอังกฤษ', 'Gifted', 2, 'Quantifiers (Item 136)', 'There are very ______ students in the library today because of the holiday. (Standard Test #136)', '["few","little","much","a little"]', 0, 'students เป็นนามนับได้พหูพจน์ ใช้ few แปลว่ามีน้อยมาก', 'Check tense, subject-verb agreement, and context', 'Look for grammar trigger keywords', '["Quantifiers (Item 136)","Gifted"]');
INSERT INTO questions (id, subject, subject_name, track, difficulty, topic, question, options_json, correct_answer, explanation, trap, shortcut_trick, tags_json) VALUES ('e_137', 'english', 'ภาษาอังกฤษ', 'Regular', 3, 'Prepositions (Item 137)', 'Are you interested ______ joining our English conversation club? (Standard Test #137)', '["in","at","for","with"]', 0, 'interested คู่กับบุพบท in เสมอ (interested in = สนใจใน)', 'Check tense, subject-verb agreement, and context', 'Look for grammar trigger keywords', '["Prepositions (Item 137)","Regular"]');
INSERT INTO questions (id, subject, subject_name, track, difficulty, topic, question, options_json, correct_answer, explanation, trap, shortcut_trick, tags_json) VALUES ('e_138', 'english', 'ภาษาอังกฤษ', 'Gifted', 1, 'Idioms (Item 138)', 'Passing the final exam was a ______ for him because he studied very hard. (Standard Test #138)', '["piece of cake","cup of tea","cold feet","spill the beans"]', 0, 'a piece of cake เป็นสำนวนแปลว่า ง่ายมากๆ', 'Check tense, subject-verb agreement, and context', 'Look for grammar trigger keywords', '["Idioms (Item 138)","Gifted"]');
INSERT INTO questions (id, subject, subject_name, track, difficulty, topic, question, options_json, correct_answer, explanation, trap, shortcut_trick, tags_json) VALUES ('e_139', 'english', 'ภาษาอังกฤษ', 'Regular', 2, 'Conjunctions (Item 139)', '______ it was raining heavily, we enjoyed our picnic in the park. (Standard Test #139)', '["Although","Because","Therefore","Despite of"]', 0, 'Although (แม้ว่า) ใช้เชื่อมประโยคที่แสดงความขัดแย้ง', 'Check tense, subject-verb agreement, and context', 'Look for grammar trigger keywords', '["Conjunctions (Item 139)","Regular"]');
