INSERT INTO questions (id, subject, subject_name, track, difficulty, topic, question, options_json, correct_answer, explanation, trap, shortcut_trick, tags_json) VALUES ('e_174', 'english', 'ภาษาอังกฤษ', 'Gifted', 1, 'Idioms (Item 174)', 'Passing the final exam was a ______ for him because he studied very hard. (Standard Test #174)', '["piece of cake","cup of tea","cold feet","spill the beans"]', 0, 'a piece of cake เป็นสำนวนแปลว่า ง่ายมากๆ', 'Check tense, subject-verb agreement, and context', 'Look for grammar trigger keywords', '["Idioms (Item 174)","Gifted"]');
INSERT INTO questions (id, subject, subject_name, track, difficulty, topic, question, options_json, correct_answer, explanation, trap, shortcut_trick, tags_json) VALUES ('e_175', 'english', 'ภาษาอังกฤษ', 'Regular', 2, 'Conjunctions (Item 175)', '______ it was raining heavily, we enjoyed our picnic in the park. (Standard Test #175)', '["Although","Because","Therefore","Despite of"]', 0, 'Although (แม้ว่า) ใช้เชื่อมประโยคที่แสดงความขัดแย้ง', 'Check tense, subject-verb agreement, and context', 'Look for grammar trigger keywords', '["Conjunctions (Item 175)","Regular"]');
