INSERT INTO questions (id, subject, subject_name, track, difficulty, topic, question, options_json, correct_answer, explanation, trap, shortcut_trick, tags_json) VALUES ('e_179', 'english', 'ภาษาอังกฤษ', 'Regular', 3, 'Passive Voice (Item 179)', 'The famous novel ______ by a Thai author in 1995. (Standard Test #179)', '["was written","wrote","is written","was writing"]', 0, 'ประธานเป็นผู้ถูกกระทำในอดีต: S + was/were + V.3 (was written)', 'Check tense, subject-verb agreement, and context', 'Look for grammar trigger keywords', '["Passive Voice (Item 179)","Regular"]');
