INSERT INTO questions (id, subject, subject_name, track, difficulty, topic, question, options_json, correct_answer, explanation, trap, shortcut_trick, tags_json) VALUES ('t_001', 'thai', 'ภาษาไทย', 'Regular', 2, 'บาลี vs สันสกฤต (ข้อที่ 1)', 'ข้อใดมีคำยืมที่มาจากภาษา สันสกฤต ทุกคำ (ข้อสอบมาตรฐานที่ 1)', '["กษัตริย์, ศรัทธา, วิทยา, ปรัชญา","มัจฉา, ปัญญา, ทัพพี","เขนย, ฉลอง, บังเอิญ","เก้าอี้, เต้าหู้, โต๊ะ"]', 0, 'สันสกฤตมีตัว ศ, ษ, ฤ, ควบกล้ำ และ รร', 'สังเกตหลักไวยากรณ์และการใช้ภาษาไทย', 'ท่องจำกฎเกณฑ์ทางภาษา', '["บาลี vs สันสกฤต (ข้อที่ 1)","Regular"]');
INSERT INTO questions (id, subject, subject_name, track, difficulty, topic, question, options_json, correct_answer, explanation, trap, shortcut_trick, tags_json) VALUES ('t_002', 'thai', 'ภาษาไทย', 'Gifted', 3, 'โวหารภาพพจน์ (ข้อที่ 2)', '"เสียงฟ้าร้องคำรามกึกก้องประหนึ่งเสียงยักษ์ตวาด" ใช้โวหารภาพพจน์ใด (ข้อสอบมาตรฐานที่ 2)', '["อุปมา (Simile - เปรียบเหมือน)","อุปลักษณ์ (Metaphor - เปรียบเป็น)","บุคลาธิษฐาน","สัทพจน์"]', 0, 'มีคำเชื่อมเปรียบเทียบคำว่า ประหนึ่ง จัดเป็น อุปมาโวหาร', 'สังเกตหลักไวยากรณ์และการใช้ภาษาไทย', 'ท่องจำกฎเกณฑ์ทางภาษา', '["โวหารภาพพจน์ (ข้อที่ 2)","Gifted"]');
INSERT INTO questions (id, subject, subject_name, track, difficulty, topic, question, options_json, correct_answer, explanation, trap, shortcut_trick, tags_json) VALUES ('t_003', 'thai', 'ภาษาไทย', 'Regular', 1, 'คำซ้อนเพื่อเสียง (ข้อที่ 3)', 'ข้อใดเป็น คำซ้อนเพื่อเสียง ทุกคำ (ข้อสอบมาตรฐานที่ 3)', '["ตูมตาม, ซุบซิบ, งงงวย, ออดแอด","บ้านเรือน, เสื้อผ้า, จิตใจ","ยากง่าย, เท็จจริง, ดีชั่ว","แม่น้ำ, รถไฟ, น้ำปลา"]', 0, 'ตูมตาม ซุบซิบ เป็นคำซ้อนที่เน้นเสียงสัมผัสเพื่อความไพเราะ', 'สังเกตหลักไวยากรณ์และการใช้ภาษาไทย', 'ท่องจำกฎเกณฑ์ทางภาษา', '["คำซ้อนเพื่อเสียง (ข้อที่ 3)","Regular"]');
INSERT INTO questions (id, subject, subject_name, track, difficulty, topic, question, options_json, correct_answer, explanation, trap, shortcut_trick, tags_json) VALUES ('t_004', 'thai', 'ภาษาไทย', 'Gifted', 2, 'เจตนาการสื่อสาร (ข้อที่ 4)', '"กรุณาถอดรองเท้าก่อนเข้าห้องสมุด" เป็นประโยคชนิดใด (ข้อสอบมาตรฐานที่ 4)', '["ประโยคขอร้อง","ประโยคคำสั่ง","ประโยคบอกเล่า","ประโยคเงื่อนไข"]', 0, 'มีคำว่า กรุณา แสดงเจตนาขอร้องอย่างสุภาพ', 'สังเกตหลักไวยากรณ์และการใช้ภาษาไทย', 'ท่องจำกฎเกณฑ์ทางภาษา', '["เจตนาการสื่อสาร (ข้อที่ 4)","Gifted"]');
INSERT INTO questions (id, subject, subject_name, track, difficulty, topic, question, options_json, correct_answer, explanation, trap, shortcut_trick, tags_json) VALUES ('t_005', 'thai', 'ภาษาไทย', 'Regular', 3, 'การผันวรรณยุกต์ (ข้อที่ 5)', 'คำว่า "ไม้" มีรูปและเสียงวรรณยุกต์ใด (ข้อสอบมาตรฐานที่ 5)', '["รูปโท แต่เสียงตรี","รูปโท เสียงโท","รูปเอก เสียงโท","รูปตรี เสียงตรี"]', 0, 'อักษรต่ำ (ม) เมื่อใส่รูปไม้โท จะออกเสียงเป็นเสียงตรี', 'สังเกตหลักไวยากรณ์และการใช้ภาษาไทย', 'ท่องจำกฎเกณฑ์ทางภาษา', '["การผันวรรณยุกต์ (ข้อที่ 5)","Regular"]');
INSERT INTO questions (id, subject, subject_name, track, difficulty, topic, question, options_json, correct_answer, explanation, trap, shortcut_trick, tags_json) VALUES ('t_006', 'thai', 'ภาษาไทย', 'Gifted', 1, 'คำพ้องรูป (ข้อที่ 6)', 'คำคู่ใดจัดเป็น คำพ้องรูป (เขียนเหมือนกันแต่อ่านต่างกัน) (ข้อสอบมาตรฐานที่ 6)', '["เพลา (เพ-ลา / เพลา)","การ / กาล / กานต์","บาท / บาตร","ขัน / ขัน"]', 0, 'เพลา อ่านได้ทั้ง เพ-ลา (เวลา) และ เพลา (เบาลง)', 'สังเกตหลักไวยากรณ์และการใช้ภาษาไทย', 'ท่องจำกฎเกณฑ์ทางภาษา', '["คำพ้องรูป (ข้อที่ 6)","Gifted"]');
