INSERT INTO questions (id, subject, subject_name, track, difficulty, topic, question, options_json, correct_answer, explanation, trap, shortcut_trick, tags_json) VALUES ('t_041', 'thai', 'ภาษาไทย', 'Regular', 3, 'บาลี vs สันสกฤต (ข้อที่ 41)', 'ข้อใดมีคำยืมที่มาจากภาษา สันสกฤต ทุกคำ (ข้อสอบมาตรฐานที่ 41)', '["กษัตริย์, ศรัทธา, วิทยา, ปรัชญา","มัจฉา, ปัญญา, ทัพพี","เขนย, ฉลอง, บังเอิญ","เก้าอี้, เต้าหู้, โต๊ะ"]', 0, 'สันสกฤตมีตัว ศ, ษ, ฤ, ควบกล้ำ และ รร', 'สังเกตหลักไวยากรณ์และการใช้ภาษาไทย', 'ท่องจำกฎเกณฑ์ทางภาษา', '["บาลี vs สันสกฤต (ข้อที่ 41)","Regular"]');
INSERT INTO questions (id, subject, subject_name, track, difficulty, topic, question, options_json, correct_answer, explanation, trap, shortcut_trick, tags_json) VALUES ('t_042', 'thai', 'ภาษาไทย', 'Gifted', 1, 'โวหารภาพพจน์ (ข้อที่ 42)', '"เสียงฟ้าร้องคำรามกึกก้องประหนึ่งเสียงยักษ์ตวาด" ใช้โวหารภาพพจน์ใด (ข้อสอบมาตรฐานที่ 42)', '["อุปมา (Simile - เปรียบเหมือน)","อุปลักษณ์ (Metaphor - เปรียบเป็น)","บุคลาธิษฐาน","สัทพจน์"]', 0, 'มีคำเชื่อมเปรียบเทียบคำว่า ประหนึ่ง จัดเป็น อุปมาโวหาร', 'สังเกตหลักไวยากรณ์และการใช้ภาษาไทย', 'ท่องจำกฎเกณฑ์ทางภาษา', '["โวหารภาพพจน์ (ข้อที่ 42)","Gifted"]');
