INSERT INTO questions (id, subject, subject_name, track, difficulty, topic, question, options_json, correct_answer, explanation, trap, shortcut_trick, tags_json) VALUES ('t_109', 'thai', 'ภาษาไทย', 'Regular', 2, 'คำสมาส-สนธิ (ข้อที่ 109)', 'คำในข้อใดเกิดจากการ สนธิ (กลมกลืนเสียง) (ข้อสอบมาตรฐานที่ 109)', '["มเหสี (มหา + อิสี), สมาคม (สัม + อาคม)","ผลไม้, รถไฟ","ราชการ, รัฐศาสตร์","นักเรียน, หมอผี"]', 0, 'มเหสี และ สมาคม มีการเชื่อมกลมกลืนเสียงของสระและพยัญชนะ', 'สังเกตหลักไวยากรณ์และการใช้ภาษาไทย', 'ท่องจำกฎเกณฑ์ทางภาษา', '["คำสมาส-สนธิ (ข้อที่ 109)","Regular"]');
INSERT INTO questions (id, subject, subject_name, track, difficulty, topic, question, options_json, correct_answer, explanation, trap, shortcut_trick, tags_json) VALUES ('t_110', 'thai', 'ภาษาไทย', 'Gifted', 3, 'คำสุภาพ (ข้อที่ 110)', 'คำสุภาพของ "ผักบุ้ง" และ "ปลาช่อน" คือข้อใดตามลำดับ (ข้อสอบมาตรฐานที่ 110)', '["ผักทอดยอด, ปลาหาง","ผักรู้นอน, ปลามัจฉา","ผักสามหาว, ปลาย่าง","ผักก้านยาว, ปลาดำ"]', 0, 'ผักบุ้ง = ผักทอดยอด, ผักกระเฉด = ผักรู้นอน, ปลาช่อน = ปลาหาง', 'สังเกตหลักไวยากรณ์และการใช้ภาษาไทย', 'ท่องจำกฎเกณฑ์ทางภาษา', '["คำสุภาพ (ข้อที่ 110)","Gifted"]');
INSERT INTO questions (id, subject, subject_name, track, difficulty, topic, question, options_json, correct_answer, explanation, trap, shortcut_trick, tags_json) VALUES ('t_111', 'thai', 'ภาษาไทย', 'Regular', 1, 'บาลี vs สันสกฤต (ข้อที่ 111)', 'ข้อใดมีคำยืมที่มาจากภาษา สันสกฤต ทุกคำ (ข้อสอบมาตรฐานที่ 111)', '["กษัตริย์, ศรัทธา, วิทยา, ปรัชญา","มัจฉา, ปัญญา, ทัพพี","เขนย, ฉลอง, บังเอิญ","เก้าอี้, เต้าหู้, โต๊ะ"]', 0, 'สันสกฤตมีตัว ศ, ษ, ฤ, ควบกล้ำ และ รร', 'สังเกตหลักไวยากรณ์และการใช้ภาษาไทย', 'ท่องจำกฎเกณฑ์ทางภาษา', '["บาลี vs สันสกฤต (ข้อที่ 111)","Regular"]');
INSERT INTO questions (id, subject, subject_name, track, difficulty, topic, question, options_json, correct_answer, explanation, trap, shortcut_trick, tags_json) VALUES ('t_112', 'thai', 'ภาษาไทย', 'Gifted', 2, 'โวหารภาพพจน์ (ข้อที่ 112)', '"เสียงฟ้าร้องคำรามกึกก้องประหนึ่งเสียงยักษ์ตวาด" ใช้โวหารภาพพจน์ใด (ข้อสอบมาตรฐานที่ 112)', '["อุปมา (Simile - เปรียบเหมือน)","อุปลักษณ์ (Metaphor - เปรียบเป็น)","บุคลาธิษฐาน","สัทพจน์"]', 0, 'มีคำเชื่อมเปรียบเทียบคำว่า ประหนึ่ง จัดเป็น อุปมาโวหาร', 'สังเกตหลักไวยากรณ์และการใช้ภาษาไทย', 'ท่องจำกฎเกณฑ์ทางภาษา', '["โวหารภาพพจน์ (ข้อที่ 112)","Gifted"]');
