INSERT INTO questions (id, subject, subject_name, track, difficulty, topic, question, options_json, correct_answer, explanation, trap, shortcut_trick, tags_json) VALUES ('t_126', 'thai', 'ภาษาไทย', 'Gifted', 1, 'คำพ้องรูป (ข้อที่ 126)', 'คำคู่ใดจัดเป็น คำพ้องรูป (เขียนเหมือนกันแต่อ่านต่างกัน) (ข้อสอบมาตรฐานที่ 126)', '["เพลา (เพ-ลา / เพลา)","การ / กาล / กานต์","บาท / บาตร","ขัน / ขัน"]', 0, 'เพลา อ่านได้ทั้ง เพ-ลา (เวลา) และ เพลา (เบาลง)', 'สังเกตหลักไวยากรณ์และการใช้ภาษาไทย', 'ท่องจำกฎเกณฑ์ทางภาษา', '["คำพ้องรูป (ข้อที่ 126)","Gifted"]');
INSERT INTO questions (id, subject, subject_name, track, difficulty, topic, question, options_json, correct_answer, explanation, trap, shortcut_trick, tags_json) VALUES ('t_127', 'thai', 'ภาษาไทย', 'Regular', 2, 'คำราชาศัพท์ (ข้อที่ 127)', 'คำราชาศัพท์ของ "หน้าผาก" และ "หัวเข่า" คือข้อใดตามลำดับ (ข้อสอบมาตรฐานที่ 127)', '["พระนลาฏ, พระชานุ","พระขนง, พระอุระ","พระกรรณ, พระบาท","พระหัตถ์, พระศอ"]', 0, 'พระนลาฏ = หน้าผาก, พระชานุ = หัวเข่า', 'สังเกตหลักไวยากรณ์และการใช้ภาษาไทย', 'ท่องจำกฎเกณฑ์ทางภาษา', '["คำราชาศัพท์ (ข้อที่ 127)","Regular"]');
INSERT INTO questions (id, subject, subject_name, track, difficulty, topic, question, options_json, correct_answer, explanation, trap, shortcut_trick, tags_json) VALUES ('t_128', 'thai', 'ภาษาไทย', 'Gifted', 3, 'ชนิดของคำ (ข้อที่ 128)', 'ในประโยค "เด็กๆ ต่างคนต่างช่วยกันทำงาน" คำว่า "ต่าง" คือสรรพนามชนิดใด (ข้อสอบมาตรฐานที่ 128)', '["วิภาคสรรพนาม (สรรพนามแยกฝ่าย)","นิยมสรรพนาม","อนิยมสรรพนาม","ประพันธสรรพนาม"]', 0, 'คำว่า ต่าง, บ้าง, กัน ที่แสดงการแยกฝ่ายเป็นวิภาคสรรพนาม', 'สังเกตหลักไวยากรณ์และการใช้ภาษาไทย', 'ท่องจำกฎเกณฑ์ทางภาษา', '["ชนิดของคำ (ข้อที่ 128)","Gifted"]');
