INSERT INTO questions (id, subject, subject_name, track, difficulty, topic, question, options_json, correct_answer, explanation, trap, shortcut_trick, tags_json) VALUES ('t_160', 'thai', 'ภาษาไทย', 'Gifted', 2, 'คำสุภาพ (ข้อที่ 160)', 'คำสุภาพของ "ผักบุ้ง" และ "ปลาช่อน" คือข้อใดตามลำดับ (ข้อสอบมาตรฐานที่ 160)', '["ผักทอดยอด, ปลาหาง","ผักรู้นอน, ปลามัจฉา","ผักสามหาว, ปลาย่าง","ผักก้านยาว, ปลาดำ"]', 0, 'ผักบุ้ง = ผักทอดยอด, ผักกระเฉด = ผักรู้นอน, ปลาช่อน = ปลาหาง', 'สังเกตหลักไวยากรณ์และการใช้ภาษาไทย', 'ท่องจำกฎเกณฑ์ทางภาษา', '["คำสุภาพ (ข้อที่ 160)","Gifted"]');
INSERT INTO questions (id, subject, subject_name, track, difficulty, topic, question, options_json, correct_answer, explanation, trap, shortcut_trick, tags_json) VALUES ('t_161', 'thai', 'ภาษาไทย', 'Regular', 3, 'บาลี vs สันสกฤต (ข้อที่ 161)', 'ข้อใดมีคำยืมที่มาจากภาษา สันสกฤต ทุกคำ (ข้อสอบมาตรฐานที่ 161)', '["กษัตริย์, ศรัทธา, วิทยา, ปรัชญา","มัจฉา, ปัญญา, ทัพพี","เขนย, ฉลอง, บังเอิญ","เก้าอี้, เต้าหู้, โต๊ะ"]', 0, 'สันสกฤตมีตัว ศ, ษ, ฤ, ควบกล้ำ และ รร', 'สังเกตหลักไวยากรณ์และการใช้ภาษาไทย', 'ท่องจำกฎเกณฑ์ทางภาษา', '["บาลี vs สันสกฤต (ข้อที่ 161)","Regular"]');
INSERT INTO questions (id, subject, subject_name, track, difficulty, topic, question, options_json, correct_answer, explanation, trap, shortcut_trick, tags_json) VALUES ('t_162', 'thai', 'ภาษาไทย', 'Gifted', 1, 'โวหารภาพพจน์ (ข้อที่ 162)', '"เสียงฟ้าร้องคำรามกึกก้องประหนึ่งเสียงยักษ์ตวาด" ใช้โวหารภาพพจน์ใด (ข้อสอบมาตรฐานที่ 162)', '["อุปมา (Simile - เปรียบเหมือน)","อุปลักษณ์ (Metaphor - เปรียบเป็น)","บุคลาธิษฐาน","สัทพจน์"]', 0, 'มีคำเชื่อมเปรียบเทียบคำว่า ประหนึ่ง จัดเป็น อุปมาโวหาร', 'สังเกตหลักไวยากรณ์และการใช้ภาษาไทย', 'ท่องจำกฎเกณฑ์ทางภาษา', '["โวหารภาพพจน์ (ข้อที่ 162)","Gifted"]');
INSERT INTO questions (id, subject, subject_name, track, difficulty, topic, question, options_json, correct_answer, explanation, trap, shortcut_trick, tags_json) VALUES ('t_163', 'thai', 'ภาษาไทย', 'Regular', 2, 'คำซ้อนเพื่อเสียง (ข้อที่ 163)', 'ข้อใดเป็น คำซ้อนเพื่อเสียง ทุกคำ (ข้อสอบมาตรฐานที่ 163)', '["ตูมตาม, ซุบซิบ, งงงวย, ออดแอด","บ้านเรือน, เสื้อผ้า, จิตใจ","ยากง่าย, เท็จจริง, ดีชั่ว","แม่น้ำ, รถไฟ, น้ำปลา"]', 0, 'ตูมตาม ซุบซิบ เป็นคำซ้อนที่เน้นเสียงสัมผัสเพื่อความไพเราะ', 'สังเกตหลักไวยากรณ์และการใช้ภาษาไทย', 'ท่องจำกฎเกณฑ์ทางภาษา', '["คำซ้อนเพื่อเสียง (ข้อที่ 163)","Regular"]');
