INSERT INTO questions (id, subject, subject_name, track, difficulty, topic, question, options_json, correct_answer, explanation, trap, shortcut_trick, tags_json) VALUES ('so_116', 'social', 'สังคมศึกษา', 'Gifted', 3, 'สนธิสัญญาเบาว์ริง (ข้อที่ 116)', 'สนธิสัญญาเบาว์ริงในสมัย ร.4 ส่งผลต่อระบบเศรษฐกิจไทยอย่างไร (ข้อสอบชุดที่ 116)', '["ยกเลิกการค้าผูกขาดของพระคลังสินค้า และเก็บภาษีร้อยชักสาม","เริ่มพิมพ์ธนบัตรใช้ครั้งแรก","ยกเลิกภาษีทั้งหมด","ห้ามต่างชาติค้าขาย"]', 0, 'สนธิสัญญาเบาว์ริงเปิดเสรีทางการค้าและกำหนดภาษีศุลกากร 3% (ร้อยชักสาม)', 'วิเคราะห์ประเด็นทางประวัติศาสตร์และสังคม', 'เชื่อมโยงเหตุการณ์สำคัญ', '["สนธิสัญญาเบาว์ริง (ข้อที่ 116)","Gifted"]');
