INSERT INTO questions (id, subject, subject_name, track, difficulty, topic, question, options_json, correct_answer, explanation, trap, shortcut_trick, tags_json) VALUES ('so_145', 'social', 'สังคมศึกษา', 'Regular', 2, 'กฎหมายและหน้าที่พลเมือง (ข้อที่ 145)', 'การกระทำในข้อใดจัดเป็น ความผิดทางอาญา ที่มีโทษต่อรัฐ (ข้อสอบชุดที่ 145)', '["การลักทรัพย์หรือทำร้ายร่างกายผู้อื่น","การผิดสัญญาเช่าซื้อ","การไม่คืนเงินกู้ยืม","การละเมิดสัญญาจ้าง"]', 0, 'ลักทรัพย์และทำร้ายร่างกายเป็นคดีอาญา มีโทษจำคุกและปรับ', 'วิเคราะห์ประเด็นทางประวัติศาสตร์และสังคม', 'เชื่อมโยงเหตุการณ์สำคัญ', '["กฎหมายและหน้าที่พลเมือง (ข้อที่ 145)","Regular"]');
INSERT INTO questions (id, subject, subject_name, track, difficulty, topic, question, options_json, correct_answer, explanation, trap, shortcut_trick, tags_json) VALUES ('so_146', 'social', 'สังคมศึกษา', 'Gifted', 3, 'สนธิสัญญาเบาว์ริง (ข้อที่ 146)', 'สนธิสัญญาเบาว์ริงในสมัย ร.4 ส่งผลต่อระบบเศรษฐกิจไทยอย่างไร (ข้อสอบชุดที่ 146)', '["ยกเลิกการค้าผูกขาดของพระคลังสินค้า และเก็บภาษีร้อยชักสาม","เริ่มพิมพ์ธนบัตรใช้ครั้งแรก","ยกเลิกภาษีทั้งหมด","ห้ามต่างชาติค้าขาย"]', 0, 'สนธิสัญญาเบาว์ริงเปิดเสรีทางการค้าและกำหนดภาษีศุลกากร 3% (ร้อยชักสาม)', 'วิเคราะห์ประเด็นทางประวัติศาสตร์และสังคม', 'เชื่อมโยงเหตุการณ์สำคัญ', '["สนธิสัญญาเบาว์ริง (ข้อที่ 146)","Gifted"]');
